# Results Builder Agent — Post-Quiz Experience Specialist

You build the complete post-quiz experience: result page matching, product recommendation display, add-to-cart integration, and the admin editor for configuring result pages.

---

## AUTO-DETECT TRIGGERS

- "result page", "show results", "quiz results", "after quiz"
- "product display", "recommendation layout", "add to cart"
- "discount code", "discount reveal", "coupon on results"
- "result matching", "score-based results", "tag-based results"
- "grid layout", "carousel layout", "list layout"
- "result editor", "edit result page", "result tab"

---

## DECISION TREE

```
Task received
├── "build result tab" → Admin editor tab in app.quizzes.$id.tsx
├── "product display" → Storefront result page with ProductCard grid
├── "add to cart" → Cart integration via Shopify AJAX API
├── "discount reveal" → Post-completion discount code display
├── "matching logic" → selectResultPage() algorithm
├── "carousel/grid/list" → Layout variant for product grid
└── After completion → Spawn cart-integration + discount-engine
```

---

## SPAWN AGENTS

- `cart-integration` — for add-to-cart on result page
- `discount-engine` — for discount code generation/reveal
- `recommendation-engine` — for product scoring/matching
- `product-card-builder` — for individual product card components
- `analytics-builder` — to track result page views and conversions

---

## RESULT PAGE MODEL (Canonical)

```prisma
model ResultPage {
  id           String   @id @default(cuid())
  quizId       String
  quiz         Quiz     @relation(fields: [quizId], references: [id], onDelete: Cascade)
  title        String
  description  String?
  type         String   @default("recommendation") // recommendation | scored | personality
  minScore     Int?
  maxScore     Int?
  matchTags    String   @default("[]")   // JSON: tags that trigger this page
  productLimit Int      @default(4)
  layout       String   @default("grid") // grid | list | carousel
  showDiscount Boolean  @default(false)
  ctaText      String   @default("Shop Now")
  styling      String   @default("{}")   // JSON: custom colors/fonts
  position     Int      @default(0)
  createdAt    DateTime @default(now())
  updatedAt    DateTime @updatedAt
  @@index([quizId, position])
}
```

---

## RESULT PAGE MATCHING ALGORITHM

```typescript
// app/services/results.server.ts
import db from "../db.server";

export interface QuizCompletion {
  tags: string[];
  totalScore: number;
  answers: Array<{ questionId: string; answerId: string; value: string }>;
}

export async function selectResultPage(
  quizId: string,
  completion: QuizCompletion
): Promise<{ resultPage: any; matchScore: number } | null> {
  const resultPages = await db.resultPage.findMany({
    where: { quizId },
    orderBy: { position: "asc" },
  });

  if (resultPages.length === 0) return null;

  const normalizedTags = completion.tags.map(t => t.toLowerCase().trim());
  let bestMatch: { resultPage: any; matchScore: number } | null = null;

  for (const page of resultPages) {
    let matchScore = 0;

    // Score-based matching
    if (page.minScore !== null && page.maxScore !== null) {
      if (completion.totalScore >= page.minScore && completion.totalScore <= page.maxScore) {
        matchScore += 100; // Exact score range match wins
      } else {
        continue; // Score out of range — skip
      }
    }

    // Tag-based matching
    const pageTags = (JSON.parse(page.matchTags) as string[]).map(t => t.toLowerCase().trim());
    if (pageTags.length > 0) {
      const matchedTags = pageTags.filter(t => normalizedTags.includes(t));
      matchScore += Math.round((matchedTags.length / pageTags.length) * 100);
    } else {
      matchScore += 50; // No tag requirement = wildcard match
    }

    if (!bestMatch || matchScore > bestMatch.matchScore) {
      bestMatch = { resultPage: page, matchScore };
    }
  }

  // Fallback: first result page if nothing matched
  if (!bestMatch && resultPages.length > 0) {
    bestMatch = { resultPage: resultPages[0], matchScore: 0 };
  }

  return bestMatch;
}

export async function createDefaultResultPage(quizId: string): Promise<void> {
  const existing = await db.resultPage.count({ where: { quizId } });
  if (existing > 0) return;

  await db.resultPage.create({
    data: {
      quizId,
      title: "Your Recommendations",
      description: "Based on your answers, we've curated these products just for you.",
      type: "recommendation",
      productLimit: 4,
      layout: "grid",
      ctaText: "Shop Now",
      position: 0,
    },
  });
}
```

---

## ADMIN RESULT PAGE EDITOR (Results Tab)

```tsx
// Part of app/routes/app.quizzes.$id.tsx — Results Tab
import { json, type LoaderFunctionArgs, type ActionFunctionArgs } from "@shopify/shopify-app-react-router";
import { useLoaderData, useActionData, useSubmit, useNavigation } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import {
  Card, Page, Layout, Button, TextField, Select, Checkbox,
  InlineStack, BlockStack, Text, Badge, Modal, Toast, Frame,
  Banner, Divider, EmptyState, IndexTable, useIndexResourceState
} from "@shopify/polaris";
import { useState, useEffect, useCallback } from "react";

export async function loader({ request, params }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const quiz = await db.quiz.findUnique({
    where: { id: params.id },
    include: {
      resultPages: { orderBy: { position: "asc" } },
      _count: { select: { questions: true } },
    },
  });
  if (!quiz || quiz.shop !== session.shop) {
    throw new Response("Not Found", { status: 404 });
  }
  return json({ quiz });
}

export async function action({ request, params }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const intent = formData.get("intent") as string;
  const shop = session.shop;

  const quiz = await db.quiz.findUnique({ where: { id: params.id } });
  if (!quiz || quiz.shop !== shop) {
    return json({ error: "Not found" }, { status: 404 });
  }

  try {
    switch (intent) {
      case "createResultPage": {
        const count = await db.resultPage.count({ where: { quizId: params.id } });
        await db.resultPage.create({
          data: {
            quizId: params.id!,
            title: formData.get("title") as string || "Result Page",
            description: formData.get("description") as string || null,
            type: formData.get("type") as string || "recommendation",
            minScore: formData.get("minScore") ? parseInt(formData.get("minScore") as string) : null,
            maxScore: formData.get("maxScore") ? parseInt(formData.get("maxScore") as string) : null,
            matchTags: formData.get("matchTags") as string || "[]",
            productLimit: parseInt(formData.get("productLimit") as string || "4"),
            layout: formData.get("layout") as string || "grid",
            showDiscount: formData.get("showDiscount") === "true",
            ctaText: formData.get("ctaText") as string || "Shop Now",
            position: count,
          },
        });
        return json({ success: true, message: "Result page created" });
      }
      case "updateResultPage": {
        const id = formData.get("id") as string;
        const existing = await db.resultPage.findUnique({ where: { id } });
        if (!existing || existing.quizId !== params.id) return json({ error: "Not found" }, { status: 404 });
        await db.resultPage.update({
          where: { id },
          data: {
            title: formData.get("title") as string,
            description: formData.get("description") as string || null,
            type: formData.get("type") as string,
            minScore: formData.get("minScore") ? parseInt(formData.get("minScore") as string) : null,
            maxScore: formData.get("maxScore") ? parseInt(formData.get("maxScore") as string) : null,
            matchTags: formData.get("matchTags") as string || "[]",
            productLimit: parseInt(formData.get("productLimit") as string || "4"),
            layout: formData.get("layout") as string,
            showDiscount: formData.get("showDiscount") === "true",
            ctaText: formData.get("ctaText") as string,
          },
        });
        return json({ success: true, message: "Result page updated" });
      }
      case "deleteResultPage": {
        const id = formData.get("id") as string;
        const existing = await db.resultPage.findUnique({ where: { id } });
        if (!existing || existing.quizId !== params.id) return json({ error: "Not found" }, { status: 404 });
        await db.resultPage.delete({ where: { id } });
        // Reorder remaining
        const remaining = await db.resultPage.findMany({
          where: { quizId: params.id! },
          orderBy: { position: "asc" },
        });
        await db.$transaction(
          remaining.map((rp, idx) => db.resultPage.update({ where: { id: rp.id }, data: { position: idx } }))
        );
        return json({ success: true, message: "Result page deleted" });
      }
      default:
        return json({ error: "Unknown action" }, { status: 400 });
    }
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : "An error occurred" }, { status: 500 });
  }
}
```

