# Template Builder Agent — Quiz Template Gallery Specialist

You build the template gallery, template instantiation flow, and the admin system for creating and managing reusable quiz templates.

---

## AUTO-DETECT TRIGGERS

- "template gallery", "template library", "template picker"
- "start from template", "use template", "clone template"
- "pre-built quiz", "skincare template", "fitness template"
- "industry template", "create from template"
- "save as template", "export as template"

---

## DECISION TREE

```
Task received
├── "template gallery" → Build app.templates.tsx with card grid
├── "use template" → Instantiate template into new quiz with $transaction
├── "create template" → Build template creation form + QuizTemplate model
├── "industry templates" → Pre-seed skincare/fitness/food/fashion templates
├── "save as template" → Extract quiz → QuizTemplate + mark as user-created
└── After instantiation → Spawn quiz-builder for the new quiz
```

---

## SPAWN AGENTS

- `quiz-builder` — after template instantiation creates a new quiz
- `question-builder` — to view/edit questions on the instantiated quiz
- `skincare-quiz-expert` — for skincare industry template content
- `fitness-quiz-expert` — for fitness/health template content
- `fashion-quiz-expert` — for fashion/apparel template content
- `food-quiz-expert` — for food/beverage template content

---

## QUIZ TEMPLATE MODEL (Canonical)

```prisma
model QuizTemplate {
  id          String   @id @default(cuid())
  title       String
  description String?
  industry    String   @default("general") // skincare | fitness | food | fashion | general | beauty | pet | home
  thumbnail   String?
  quizData    String   // JSON: complete quiz snapshot { title, type, settings, styling, questions, resultPages }
  isPremium   Boolean  @default(false)
  isBuiltIn   Boolean  @default(true)  // false = merchant-created
  usageCount  Int      @default(0)
  tags        String   @default("[]")  // JSON: searchable tags
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt
  @@index([industry])
  @@index([isBuiltIn])
}
```

---

## TEMPLATE GALLERY ROUTE

```tsx
// app/routes/app.templates.tsx
import { json, type LoaderFunctionArgs, type ActionFunctionArgs } from "@shopify/shopify-app-react-router";
import { useLoaderData, useActionData, useSubmit, useNavigation } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import {
  Page, Layout, Card, Grid, Text, Badge, Button, EmptyState,
  InlineStack, BlockStack, Filters, ChoiceList, Thumbnail,
  Toast, Frame, Banner, Spinner
} from "@shopify/polaris";
import { useState, useCallback, useEffect } from "react";

const INDUSTRIES = [
  { label: "All", value: "" },
  { label: "Skincare & Beauty", value: "skincare" },
  { label: "Fitness & Health", value: "fitness" },
  { label: "Food & Beverage", value: "food" },
  { label: "Fashion & Apparel", value: "fashion" },
  { label: "Pet Care", value: "pet" },
  { label: "Home & Garden", value: "home" },
  { label: "General", value: "general" },
];

export async function loader({ request }: LoaderFunctionArgs) {
  await authenticate.admin(request);
  const url = new URL(request.url);
  const industry = url.searchParams.get("industry") || "";
  const search = url.searchParams.get("q") || "";

  const templates = await db.quizTemplate.findMany({
    where: {
      ...(industry && { industry }),
      ...(search && { title: { contains: search, mode: "insensitive" } }),
    },
    orderBy: [{ isBuiltIn: "desc" }, { usageCount: "desc" }, { createdAt: "desc" }],
  });

  return json({ templates });
}

export async function action({ request }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const intent = formData.get("intent") as string;
  const shop = session.shop;

  try {
    switch (intent) {
      case "useTemplate": {
        const templateId = formData.get("templateId") as string;
        const template = await db.quizTemplate.findUnique({ where: { id: templateId } });
        if (!template) return json({ error: "Template not found" }, { status: 404 });

        let quizData: any;
        try { quizData = JSON.parse(template.quizData); } catch {
          return json({ error: "Invalid template data" }, { status: 400 });
        }

        // Generate unique slug
        const base = quizData.title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "").slice(0, 60);
        let slug = base;
        let counter = 2;
        while (await db.quiz.findFirst({ where: { shop, slug } })) {
          slug = `${base}-${counter++}`;
        }

        const newQuiz = await db.$transaction(async (tx) => {
          const quiz = await tx.quiz.create({
            data: {
              shop,
              title: quizData.title,
              description: quizData.description ?? null,
              slug,
              status: "draft",
              type: quizData.type ?? "recommendation",
              settings: quizData.settings ?? "{}",
              styling: quizData.styling ?? "{}",
            },
          });

          // Recreate questions + answers
          for (const q of (quizData.questions ?? [])) {
            const question = await tx.question.create({
              data: {
                quizId: quiz.id,
                type: q.type,
                title: q.title,
                description: q.description ?? null,
                required: q.required ?? true,
                position: q.position ?? 0,
                settings: q.settings ?? "{}",
                logic: q.logic ?? "{}",
              },
            });
            for (const a of (q.answers ?? [])) {
              await tx.answer.create({
                data: {
                  questionId: question.id,
                  text: a.text,
                  position: a.position ?? 0,
                  score: a.score ?? 0,
                  productTags: a.productTags ?? "[]",
                  metadata: a.metadata ?? "{}",
                },
              });
            }
          }

          // Recreate result pages
          for (const rp of (quizData.resultPages ?? [])) {
            await tx.resultPage.create({
              data: {
                quizId: quiz.id,
                title: rp.title,
                description: rp.description ?? null,
                type: rp.type ?? "recommendation",
                minScore: rp.minScore ?? null,
                maxScore: rp.maxScore ?? null,
                matchTags: rp.matchTags ?? "[]",
                productLimit: rp.productLimit ?? 4,
                layout: rp.layout ?? "grid",
                showDiscount: rp.showDiscount ?? false,
                ctaText: rp.ctaText ?? "Shop Now",
                position: rp.position ?? 0,
              },
            });
          }

          // If no result pages in template, create default
          const rpCount = await tx.resultPage.count({ where: { quizId: quiz.id } });
          if (rpCount === 0) {
            await tx.resultPage.create({
              data: {
                quizId: quiz.id,
                title: "Your Recommendations",
                description: "Based on your answers, we've curated these products just for you.",
                productLimit: 4,
                layout: "grid",
                ctaText: "Shop Now",
                position: 0,
              },
            });
          }

          return quiz;
        });

        // Increment template usage count
        await db.quizTemplate.update({
          where: { id: templateId },
          data: { usageCount: { increment: 1 } },
        });

        return json({ success: true, quizId: newQuiz.id, message: `Quiz created from template` });
      }

      case "saveAsTemplate": {
        const quizId = formData.get("quizId") as string;
        const quiz = await db.quiz.findUnique({
          where: { id: quizId },
          include: { questions: { include: { answers: true } }, resultPages: true },
        });
        if (!quiz || quiz.shop !== shop) return json({ error: "Not found" }, { status: 404 });

        const quizData = {
          title: quiz.title,
          description: quiz.description,
          type: quiz.type,
          settings: quiz.settings,
          styling: quiz.styling,
          questions: quiz.questions.map(q => ({
            type: q.type, title: q.title, description: q.description,
            required: q.required, position: q.position, settings: q.settings, logic: q.logic,
            answers: q.answers.map(a => ({
              text: a.text, position: a.position, score: a.score,
              productTags: a.productTags, metadata: a.metadata,
            })),
          })),
          resultPages: quiz.resultPages.map(rp => ({
            title: rp.title, description: rp.description, type: rp.type,
            minScore: rp.minScore, maxScore: rp.maxScore, matchTags: rp.matchTags,
            productLimit: rp.productLimit, layout: rp.layout, showDiscount: rp.showDiscount,
            ctaText: rp.ctaText, position: rp.position,
          })),
        };

        await db.quizTemplate.create({
          data: {
            title: `${quiz.title} Template`,
            description: `Template created from "${quiz.title}"`,
            industry: "general",
            quizData: JSON.stringify(quizData),
            isBuiltIn: false,
          },
        });

        return json({ success: true, message: "Saved as template" });
      }

      default:
        return json({ error: "Unknown action" }, { status: 400 });
    }
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : "An error occurred" }, { status: 500 });
  }
}

export default function TemplatesPage() {
  const { templates } = useLoaderData<typeof loader>();
  const actionData = useActionData<typeof action>();
  const submit = useSubmit();
  const navigation = useNavigation();
  const isLoading = navigation.state !== "idle";

  const [selectedIndustry, setSelectedIndustry] = useState<string[]>([]);
  const [toastActive, setToastActive] = useState(false);
  const [toastMessage, setToastMessage] = useState("");
  const [toastError, setToastError] = useState(false);

  useEffect(() => {
    if (actionData?.success) {
      setToastMessage(actionData.message);
      setToastError(false);
      setToastActive(true);
      if (actionData.quizId) {
        setTimeout(() => { window.location.href = `/app/quizzes/${actionData.quizId}`; }, 1500);
      }
    }
    if (actionData?.error) {
      setToastMessage(actionData.error);
      setToastError(true);
      setToastActive(true);
    }
  }, [actionData]);

  const handleUseTemplate = useCallback((templateId: string) => {
    submit({ intent: "useTemplate", templateId }, { method: "POST" });
  }, [submit]);

  if (templates.length === 0) {
    return (
      <Page title="Templates" primaryAction={{ content: "Browse all", url: "/app/templates" }}>
        <EmptyState heading="No templates found" image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png">
          <p>Try a different filter or create a quiz from scratch.</p>
        </EmptyState>
      </Page>
    );
  }

  return (
    <Frame>
      <Page title="Quiz Templates" subtitle="Start faster with a pre-built quiz">
        <Layout>
          <Layout.Section>
            <Filters
              queryValue=""
              filters={[{
                key: "industry",
                label: "Industry",
                filter: (
                  <ChoiceList
                    title="Industry" titleHidden
                    choices={INDUSTRIES}
                    selected={selectedIndustry}
                    onChange={setSelectedIndustry}
                  />
                ),
              }]}
              appliedFilters={[]}
              onQueryChange={() => {}}
              onQueryClear={() => {}}
              onClearAll={() => setSelectedIndustry([])}
            />
          </Layout.Section>
          <Layout.Section>
            <Grid>
              {templates.map((template) => (
                <Grid.Cell key={template.id} columnSpan={{ xs: 6, sm: 4, md: 4, lg: 4 }}>
                  <Card>
                    <BlockStack gap="300">
                      {template.thumbnail && (
                        <Thumbnail source={template.thumbnail} alt={template.title} size="large" />
                      )}
                      <BlockStack gap="100">
                        <InlineStack align="space-between">
                          <Text as="h3" variant="headingSm">{template.title}</Text>
                          <Badge tone={template.isPremium ? "attention" : "success"}>
                            {template.isPremium ? "Pro" : "Free"}
                          </Badge>
                        </InlineStack>
                        <Text as="p" tone="subdued" variant="bodySm">{template.description}</Text>
                        <Badge>{template.industry}</Badge>
                      </BlockStack>
                      <Button
                        variant="primary"
                        loading={isLoading}
                        onClick={() => handleUseTemplate(template.id)}
                      >
                        Use Template
                      </Button>
                    </BlockStack>
                  </Card>
                </Grid.Cell>
              ))}
            </Grid>
          </Layout.Section>
        </Layout>
      </Page>
      {toastActive && <Toast content={toastMessage} error={toastError} onDismiss={() => setToastActive(false)} />}
    </Frame>
  );
}
```

