                productLimit: rp.productLimit ?? 4,
                layout: rp.layout ?? "grid",
                showDiscount: rp.showDiscount ?? false,
                ctaText: rp.ctaText ?? "Shop Now",
                position: rp.position ?? 0,
              },
            });
          }

          // If no result pages in template, create default
          const rpCount = await tx.resultPage.count({ where: { quizId: quiz.id } });
          if (rpCount === 0) {
            await tx.resultPage.create({
              data: {
                quizId: quiz.id,
                title: "Your Recommendations",
                description: "Based on your answers, we've curated these products just for you.",
                productLimit: 4,
                layout: "grid",
                ctaText: "Shop Now",
                position: 0,
              },
            });
          }

          return quiz;
        });

        // Increment template usage count
        await db.quizTemplate.update({
          where: { id: templateId },
          data: { usageCount: { increment: 1 } },
        });

        return json({ success: true, quizId: newQuiz.id, message: `Quiz created from template` });
      }

      case "saveAsTemplate": {
        const quizId = formData.get("quizId") as string;
        const quiz = await db.quiz.findUnique({
          where: { id: quizId },
          include: { questions: { include: { answers: true } }, resultPages: true },
        });
        if (!quiz || quiz.shop !== shop) return json({ error: "Not found" }, { status: 404 });

        const quizData = {
          title: quiz.title,
          description: quiz.description,
          type: quiz.type,
          settings: quiz.settings,
          styling: quiz.styling,
          questions: quiz.questions.map(q => ({
            type: q.type, title: q.title, description: q.description,
            required: q.required, position: q.position, settings: q.settings, logic: q.logic,
            answers: q.answers.map(a => ({
              text: a.text, position: a.position, score: a.score,
              productTags: a.productTags, metadata: a.metadata,
            })),
          })),
          resultPages: quiz.resultPages.map(rp => ({
            title: rp.title, description: rp.description, type: rp.type,
            minScore: rp.minScore, maxScore: rp.maxScore, matchTags: rp.matchTags,
            productLimit: rp.productLimit, layout: rp.layout, showDiscount: rp.showDiscount,
            ctaText: rp.ctaText, position: rp.position,
          })),
        };

        await db.quizTemplate.create({
          data: {
            title: `${quiz.title} Template`,
            description: `Template created from "${quiz.title}"`,
            industry: "general",
            quizData: JSON.stringify(quizData),
            isBuiltIn: false,
          },
        });

        return json({ success: true, message: "Saved as template" });
      }

      default:
        return json({ error: "Unknown action" }, { status: 400 });
    }
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : "An error occurred" }, { status: 500 });
  }
}

export default function TemplatesPage() {
  const { templates } = useLoaderData<typeof loader>();
  const actionData = useActionData<typeof action>();
  const submit = useSubmit();
  const navigation = useNavigation();
  const isLoading = navigation.state !== "idle";

  const [selectedIndustry, setSelectedIndustry] = useState<string[]>([]);
  const [toastActive, setToastActive] = useState(false);
  const [toastMessage, setToastMessage] = useState("");
