  useEffect(() => {
    if (actionData?.success) {
      setToastMessage(actionData.message);
      setToastError(false);
      setToastActive(true);
      if (actionData.quizId) {
        setTimeout(() => { window.location.href = `/app/quizzes/${actionData.quizId}`; }, 1500);
      }
    }
    if (actionData?.error) {
      setToastMessage(actionData.error);
      setToastError(true);
      setToastActive(true);
    }
  }, [actionData]);

  const handleUseTemplate = useCallback((templateId: string) => {
    submit({ intent: "useTemplate", templateId }, { method: "POST" });
  }, [submit]);

  if (templates.length === 0) {
    return (
      <Page title="Templates" primaryAction={{ content: "Browse all", url: "/app/templates" }}>
        <EmptyState heading="No templates found" image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png">
          <p>Try a different filter or create a quiz from scratch.</p>
        </EmptyState>
      </Page>
    );
  }

  return (
    <Frame>
      <Page title="Quiz Templates" subtitle="Start faster with a pre-built quiz">
        <Layout>
          <Layout.Section>
            <Filters
              queryValue=""
              filters={[{
                key: "industry",
                label: "Industry",
                filter: (
                  <ChoiceList
                    title="Industry" titleHidden
                    choices={INDUSTRIES}
                    selected={selectedIndustry}
                    onChange={setSelectedIndustry}
                  />
                ),
              }]}
              appliedFilters={[]}
              onQueryChange={() => {}}
              onQueryClear={() => {}}
              onClearAll={() => setSelectedIndustry([])}
            />
          </Layout.Section>
          <Layout.Section>
            <Grid>
              {templates.map((template) => (
                <Grid.Cell key={template.id} columnSpan={{ xs: 6, sm: 4, md: 4, lg: 4 }}>
                  <Card>
                    <BlockStack gap="300">
                      {template.thumbnail && (
                        <Thumbnail source={template.thumbnail} alt={template.title} size="large" />
                      )}
                      <BlockStack gap="100">
                        <InlineStack align="space-between">
                          <Text as="h3" variant="headingSm">{template.title}</Text>
                          <Badge tone={template.isPremium ? "attention" : "success"}>
                            {template.isPremium ? "Pro" : "Free"}
                          </Badge>
                        </InlineStack>
                        <Text as="p" tone="subdued" variant="bodySm">{template.description}</Text>
                        <Badge>{template.industry}</Badge>
                      </BlockStack>
                      <Button
                        variant="primary"
                        loading={isLoading}
                        onClick={() => handleUseTemplate(template.id)}
                      >
                        Use Template
                      </Button>
                    </BlockStack>
                  </Card>
                </Grid.Cell>
              ))}
            </Grid>
          </Layout.Section>
        </Layout>
      </Page>
      {toastActive && <Toast content={toastMessage} error={toastError} onDismiss={() => setToastActive(false)} />}
    </Frame>
  );
}
```

