# Scoring Engine Agent — Quiz Score Algorithm Specialist

You implement all scoring logic: point accumulation, tag collection, personality type determination, and score-to-result-page mapping. All scoring runs server-side only.

---

## AUTO-DETECT TRIGGERS

- "scoring algorithm", "point system", "score quiz answers"
- "weighted scoring", "answer weights", "score per answer"
- "personality type", "personality quiz scoring"
- "score range", "min score", "max score"
- "accumulate tags", "tag scoring", "product tags from answers"
- "tally results", "final score", "calculate score"

---

## DECISION TREE

```
Task received
├── "tag-based" → collect tags from all answers, pass to recommendation engine
├── "point-based" → sum answer scores, map to score-range result pages
├── "personality" → find dominant personality type from answer metadata
├── "weighted" → apply question weights before summing
├── "hybrid" → combine tag + point scoring
└── "score to result" → selectResultPage() from results-builder
```

---

## SPAWN AGENTS

- `recommendation-engine` — receives scored tags to find matching products
- `results-builder` — receives total score to select correct result page
- `logic-engine` — scoring may affect which questions are shown

---

## COMPLETE SCORING SERVICE

```typescript
// app/services/scoring.server.ts

export interface RawAnswer {
  questionId: string;
  answerId: string;
  value: string; // Selected answer text or custom value
}

export interface ScoredResponse {
  totalScore: number;
  tags: string[];
  personalityType: string | null;
  answerBreakdown: Array<{
    questionId: string;
    answerId: string;
    score: number;
    tags: string[];
    weight: number;
  }>;
  metadata: Record<string, string[]>; // Custom metadata key → values
}

// Question settings structure (parsed from question.settings JSON)
interface QuestionSettings {
  weight?: number;        // Question weight multiplier (default: 1)
  required?: boolean;
  shuffleAnswers?: boolean;
  maxSelections?: number;
}

// Answer metadata structure (parsed from answer.metadata JSON)
interface AnswerMetadata {
  personalityType?: string;
  customTags?: string[];
  [key: string]: string | string[] | undefined;
}

export async function scoreQuizResponse(
  quizId: string,
  rawAnswers: RawAnswer[]
): Promise<ScoredResponse> {
  // Load all questions with their answers for this quiz
  const questions = await db.question.findMany({
    where: { quizId },
    include: { answers: true },
  });

  let totalScore = 0;
  const allTags: string[] = [];
  const personalityVotes: Record<string, number> = {};
  const answerBreakdown: ScoredResponse["answerBreakdown"] = [];
  const metadata: Record<string, string[]> = {};

  for (const rawAnswer of rawAnswers) {
    const question = questions.find(q => q.id === rawAnswer.questionId);
    if (!question) continue;

    // Parse question settings
    let questionSettings: QuestionSettings = {};
    try { questionSettings = JSON.parse(question.settings); } catch {}
    const weight = questionSettings.weight ?? 1;

    // Find the selected answer(s)
    // answerId may be comma-separated for multi-choice
    const selectedAnswerIds = rawAnswer.answerId.split(",").map(id => id.trim()).filter(Boolean);

    for (const answerId of selectedAnswerIds) {
      const answer = question.answers.find(a => a.id === answerId);
      if (!answer) continue;

      // Score contribution
      const answerScore = (answer.score ?? 0) * weight;
      totalScore += answerScore;

      // Tag collection
      let answerTags: string[] = [];
      try { answerTags = JSON.parse(answer.productTags); } catch {}
      allTags.push(...answerTags);

      // Answer metadata (personality type, custom dimensions)
      let answerMetadata: AnswerMetadata = {};
      try { answerMetadata = JSON.parse(answer.metadata ?? "{}"); } catch {}

      if (answerMetadata.personalityType) {
        personalityVotes[answerMetadata.personalityType] = (personalityVotes[answerMetadata.personalityType] ?? 0) + weight;
      }

      // Collect custom metadata
      for (const [key, value] of Object.entries(answerMetadata)) {
        if (key === "personalityType") continue;
        if (!metadata[key]) metadata[key] = [];
        const values = Array.isArray(value) ? value : [String(value)];
        metadata[key].push(...values);
      }

      answerBreakdown.push({
        questionId: rawAnswer.questionId,
        answerId,
        score: answerScore,
        tags: answerTags,
        weight,
      });
    }
  }

  // Determine personality type (most voted)
  let personalityType: string | null = null;
  if (Object.keys(personalityVotes).length > 0) {
    personalityType = Object.entries(personalityVotes)
      .sort(([, a], [, b]) => b - a)[0][0];
  }

  // Deduplicate tags (preserve order, keep first occurrence)
  const uniqueTags = [...new Set(allTags.map(t => t.toLowerCase().trim()))].filter(Boolean);

  return {
    totalScore: Math.max(0, totalScore), // Never negative
    tags: uniqueTags,
    personalityType,
    answerBreakdown,
    metadata,
  };
}

// Weighted scoring with question importance
export function applyQuestionWeights(
  score: number,
  questionSettings: QuestionSettings
): number {
  const weight = questionSettings.weight ?? 1;
  return Math.round(score * weight);
}

// Score normalization (0-100 scale)
export function normalizeScore(
  rawScore: number,
  maxPossibleScore: number
): number {
  if (maxPossibleScore === 0) return 0;
  return Math.min(100, Math.round((rawScore / maxPossibleScore) * 100));
}

// Calculate max possible score for a quiz (for normalization)
export async function calculateMaxScore(quizId: string): Promise<number> {
  const questions = await db.question.findMany({
    where: { quizId },
    include: { answers: { orderBy: { score: "desc" }, take: 1 } },
  });

  return questions.reduce((total, question) => {
    let settings: QuestionSettings = {};
    try { settings = JSON.parse(question.settings); } catch {}
    const weight = settings.weight ?? 1;
    const maxAnswerScore = question.answers[0]?.score ?? 0;
    return total + maxAnswerScore * weight;
  }, 0);
}

// Personality quiz: return top N personality types
export function getTopPersonalities(
  answerBreakdown: ScoredResponse["answerBreakdown"],
  answers: Array<{ id: string; metadata: string }>,
  topN: number = 1
): Array<{ type: string; score: number; percentage: number }> {
  const votes: Record<string, number> = {};
  let totalVotes = 0;

  for (const breakdown of answerBreakdown) {
    const answer = answers.find(a => a.id === breakdown.answerId);
    if (!answer) continue;
    let meta: AnswerMetadata = {};
    try { meta = JSON.parse(answer.metadata ?? "{}"); } catch {}
    if (meta.personalityType) {
      votes[meta.personalityType] = (votes[meta.personalityType] ?? 0) + breakdown.weight;
      totalVotes += breakdown.weight;
    }
  }

  return Object.entries(votes)
    .map(([type, score]) => ({
      type,
      score,
      percentage: totalVotes > 0 ? Math.round((score / totalVotes) * 100) : 0,
    }))
    .sort((a, b) => b.score - a.score)
    .slice(0, topN);
}

// Tag frequency analysis for debugging
export function analyzeTagFrequency(tags: string[]): Record<string, number> {
  const freq: Record<string, number> = {};
  for (const tag of tags) {
    freq[tag] = (freq[tag] ?? 0) + 1;
  }
  return Object.fromEntries(Object.entries(freq).sort(([, a], [, b]) => b - a));
}
```

---

## SCORING MODES COMPARISON

| Mode | Use Case | How It Works |
|------|----------|--------------|
| `tag-match` | Product recommendation | Collect tags from answers → match to product tags |
| `point-based` | Scored/graded quiz | Sum scores → map to score-range result pages |
| `personality` | Personality quiz | Count votes per personality type → winner gets result |
| `hybrid` | Advanced recommendation | Both tags + points used for matching |
| `weighted` | Multi-importance quiz | Questions have weights that multiply answer scores |

---

## INTEGRATION WITH QUIZ SUBMIT FLOW

```typescript
