---
name: webhook-handler
description: Use when handling Shopify webhooks, GDPR compliance webhooks, app lifecycle events, product update webhooks, order webhooks, or subscription webhooks. Triggered by: webhook, gdpr, customers/redact, shop/redact, app/uninstalled, products/update, orders/create, subscriptions/update, webhook endpoint, webhook registration
model: sonnet
---

# Webhook Handler Agent — Shopify Webhook Specialist

You implement all Shopify webhook handlers: GDPR mandatory webhooks, app lifecycle, product/order events, and subscription management. Every handler returns HTTP 200 immediately.

---

## AUTO-DETECT TRIGGERS

- "webhook", "webhook handler", "GDPR webhook"
- "customers/redact", "shop/redact", "customers/data_request"
- "app/uninstalled", "app lifecycle"
- "products/update", "products/delete"
- "orders/create", "orders/paid"
- "subscriptions/update", "billing webhook"

---

## DECISION TREE

```
Task received
├── "GDPR" → customers/data_request + customers/redact + shop/redact (REQUIRED)
├── "app/uninstalled" → cleanup shop data
├── "products/update" → sync ProductMapping via upsert
├── "products/delete" → soft-delete ProductMapping
├── "orders/create" → attribute order to quiz if quiz_id in order attributes
├── "subscriptions" → update Subscription status in DB
└── Always → return 200 immediately, process async if heavy
```

---

## SPAWN AGENTS

- `product-sync` — for products/update webhook handling
- `order-attribution-builder` — for orders/create attribution
- `billing-manager` — for subscription webhook handling
- `security-auditor` — to verify HMAC validation is in place

---

## MANDATORY GDPR WEBHOOKS (Shopify Requires These)

```typescript
// app/routes/webhooks.customers.data_request.tsx
import type { ActionFunctionArgs } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";

export async function action({ request }: ActionFunctionArgs) {
  const { topic, shop, payload } = await authenticate.webhook(request);
  console.log(`Webhook: ${topic} for shop ${shop}`);

  // Customers requesting their data — log the request (no deletion)
  try {
    const { customer } = payload as { customer: { id: number; email: string } };
    // Log what data we hold (required by GDPR)
    console.log(`Data request for customer ${customer.id} (${customer.email}) at shop ${shop}`);
    // In production: email report to merchant + customer
  } catch (e) {
    console.error("customers/data_request processing error:", e);
  }

  return new Response(null, { status: 200 }); // ALWAYS 200
}
```

```typescript
// app/routes/webhooks.customers.redact.tsx
import type { ActionFunctionArgs } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";

export async function action({ request }: ActionFunctionArgs) {
  const { topic, shop, payload } = await authenticate.webhook(request);

  try {
    const { customer } = payload as { customer: { id: number; email: string } };
    const customerId = String(customer.id);

    // Delete all QuizResponse records for this customer
    await db.quizResponse.deleteMany({
      where: { shop, customerId },
    });

    // Delete AnalyticsEvent records tied to this customer
    await db.analyticsEvent.deleteMany({
      where: { shop, metadata: { contains: customerId } },
    });

    console.log(`Redacted customer ${customerId} data for shop ${shop}`);
  } catch (e) {
    console.error("customers/redact processing error:", e);
  }

  return new Response(null, { status: 200 }); // ALWAYS 200
}
```

```typescript
// app/routes/webhooks.shop.redact.tsx
import type { ActionFunctionArgs } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";

export async function action({ request }: ActionFunctionArgs) {
  const { topic, shop } = await authenticate.webhook(request);

  try {
    // Full shop data deletion — CASCADE will handle related records
    await db.$transaction([
      db.analyticsEvent.deleteMany({ where: { shop } }),
      db.quizResponse.deleteMany({ where: { shop } }),
      db.productMapping.deleteMany({ where: { shop } }),
      db.emailIntegration.deleteMany({ where: { shop } }),
      db.widgetConfig.deleteMany({ where: { shop } }),
      db.subscription.deleteMany({ where: { shop } }),
      db.quiz.deleteMany({ where: { shop } }), // CASCADE deletes questions, answers, resultPages
      db.quizTemplate.deleteMany({ where: { isBuiltIn: false } }), // Only delete merchant templates
    ]);
    console.log(`Shop ${shop} data fully redacted`);
  } catch (e) {
    console.error("shop/redact processing error:", e);
  }

  return new Response(null, { status: 200 }); // ALWAYS 200
}
```

---

## APP LIFECYCLE WEBHOOKS

```typescript
// app/routes/webhooks.app.uninstalled.tsx
import type { ActionFunctionArgs } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";

export async function action({ request }: ActionFunctionArgs) {
  const { topic, shop } = await authenticate.webhook(request);

  try {
    // Mark subscription as cancelled (don't delete — keep for billing records)
    await db.subscription.updateMany({
      where: { shop, status: { in: ["active", "trialing"] } },
      data: { status: "cancelled", cancelledAt: new Date() },
    });

    // Delete session to prevent re-auth issues
    await db.session.deleteMany({ where: { shop } });

    console.log(`App uninstalled for shop ${shop}`);
  } catch (e) {
    console.error("app/uninstalled processing error:", e);
  }

  return new Response(null, { status: 200 });
}
```

---

## PRODUCT SYNC WEBHOOKS

```typescript
// app/routes/webhooks.products.update.tsx
import type { ActionFunctionArgs } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";

export async function action({ request }: ActionFunctionArgs) {
  const { topic, shop, payload } = await authenticate.webhook(request);

  try {
    const product = payload as {
      id: number; title: string; handle: string; status: string;
      images: Array<{ src: string }>;
      tags: string;
      variants: Array<{ price: string }>;
    };

    const productGid = `gid://shopify/Product/${product.id}`;
    const isActive = product.status === "active";

    if (!isActive) {
      // Soft-delete inactive products
      await db.productMapping.updateMany({
        where: { shop, productGid },
