name: cart-integration
description: Use when building add-to-cart functionality from quiz results, cart drawer integration, variant selection on result pages, multi-product add to cart, or checkout redirect from quiz. Triggered by: add to cart, cart integration, cart drawer, checkout, variant selection, buy now, add products to cart, cart API
model: sonnet
---

# Cart Integration Agent — Quiz-to-Cart Specialist

You implement the complete flow from quiz recommendation to Shopify cart, including variant selection, multi-product add-to-cart, and checkout redirect. All cart operations run client-side via Shopify AJAX API.

---

## AUTO-DETECT TRIGGERS

- "add to cart", "add recommended products to cart"
- "cart integration", "cart drawer", "cart API"
- "variant selection", "choose variant", "select size/color"
- "checkout redirect", "go to checkout", "buy now"
- "multi-product cart", "add all to cart"

---

## DECISION TREE

```
Task received
├── "add to cart" → Single product add via AJAX API
├── "add all to cart" → Batch add multiple recommended products
├── "variant selection" → Fetch variants, show selector before adding
├── "buy now" → Add to cart + immediate checkout redirect
├── "cart drawer" → Open Shopify cart drawer after adding
└── After adding → Track analytics event "add_to_cart"
```

---

## SPAWN AGENTS

- `results-builder` — for result page layout containing cart buttons
- `analytics-builder` — to track cart events for conversion attribution
- `discount-engine` — if discount applies at checkout

---

## SHOPIFY AJAX CART API IMPLEMENTATION

```typescript
// extensions/quiz-widget/assets/cart.ts

export interface CartItem {
  variantId: number;
  quantity: number;
  properties?: Record<string, string>;
}

export interface CartResponse {
  item_count: number;
  items: Array<{ id: number; title: string; quantity: number; price: number }>;
}

// Add single item to cart
export async function addToCart(item: CartItem): Promise<CartResponse> {
  const response = await fetch("/cart/add.js", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      items: [{
        id: item.variantId,
        quantity: item.quantity,
        properties: {
          ...item.properties,
          _quiz_source: "quizsnap", // Attribution tracking
        },
      }],
    }),
  });

  if (!response.ok) {
    const error = await response.json();
    throw new Error(error.description ?? "Failed to add to cart");
  }

  return response.json();
}

// Add multiple products at once (recommended products)
export async function addAllToCart(items: CartItem[]): Promise<CartResponse> {
  const response = await fetch("/cart/add.js", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      items: items.map(item => ({
        id: item.variantId,
        quantity: item.quantity,
        properties: { _quiz_source: "quizsnap" },
      })),
    }),
  });

  if (!response.ok) {
    const error = await response.json();
    throw new Error(error.description ?? "Failed to add products to cart");
  }

  return response.json();
}

// Get product variants for selector
export async function getProductVariants(productHandle: string): Promise<{
  variants: Array<{ id: number; title: string; available: boolean; price: string }>;
  title: string;
}> {
  const response = await fetch(`/products/${productHandle}.js`);
  if (!response.ok) throw new Error("Product not found");
  const product = await response.json();
  return {
    title: product.title,
    variants: product.variants.map((v: any) => ({
      id: v.id,
      title: v.title,
      available: v.available,
      price: (v.price / 100).toFixed(2),
    })),
  };
}

// Buy now — add to cart then redirect to checkout
export async function buyNow(item: CartItem): Promise<void> {
  await addToCart(item);
  window.location.href = "/checkout";
}

// Open cart drawer (theme-dependent)
export function openCartDrawer(): void {
  // Trigger theme's cart drawer event
  document.dispatchEvent(new CustomEvent("cart:open"));
  // Fallback: try common theme patterns
  const drawerTrigger = document.querySelector<HTMLElement>(
    '[data-cart-toggle], .cart-toggle, #cart-icon-bubble'
  );
  drawerTrigger?.click();
}

// Update cart item count in header
export async function refreshCartCount(): Promise<void> {
  const response = await fetch("/cart.js");
  const cart = await response.json();
  const countEl = document.querySelector<HTMLElement>('[data-cart-count], .cart-count, #CartCount');
  if (countEl) countEl.textContent = String(cart.item_count);
}
```

---

## VARIANT SELECTOR COMPONENT (Storefront Widget)

```javascript
// Render variant selector modal before adding to cart
function renderVariantSelector(container, product, onSelect) {
  const { variants, title } = product;
  const availableVariants = variants.filter(v => v.available);

  if (availableVariants.length === 1) {
    // Only one variant — add directly
    onSelect(availableVariants[0].id);
    return;
  }

  const modal = document.createElement('div');
  modal.className = 'qs-variant-modal';
  modal.innerHTML = `
    <div class="qs-variant-overlay"></div>
    <div class="qs-variant-dialog">
      <div class="qs-variant-header">
        <h3>${escapeHtml(title)}</h3>
        <button class="qs-variant-close" aria-label="Close">×</button>
      </div>
      <div class="qs-variant-options">
        ${availableVariants.map(v => `
          <button class="qs-variant-option" data-variant-id="${v.id}">
            ${escapeHtml(v.title)} — $${v.price}
          </button>
        `).join('')}
        ${variants.filter(v => !v.available).map(v => `
          <button class="qs-variant-option" disabled>
            ${escapeHtml(v.title)} — Sold out
          </button>
        `).join('')}
      </div>
    </div>
  `;

  document.body.appendChild(modal);

  modal.querySelector('.qs-variant-close')?.addEventListener('click', () => modal.remove());
  modal.querySelector('.qs-variant-overlay')?.addEventListener('click', () => modal.remove());
  modal.querySelectorAll('.qs-variant-option:not([disabled])').forEach(btn => {
    btn.addEventListener('click', () => {
      const variantId = parseInt(btn.getAttribute('data-variant-id') || '0');
      modal.remove();
      onSelect(variantId);
    });
  });
}

// Main add-to-cart handler called from product card CTA
async function handleAddToCart(productHandle, variantId, button, quizSessionId) {
  // If we have a variantId, add directly
  if (variantId) {
    await performAdd(variantId, button, quizSessionId);
    return;
  }

  // Otherwise fetch variants and show selector
  button.textContent = 'Loading...';
  button.disabled = true;
  try {
    const product = await getProductVariants(productHandle);
    button.textContent = button.dataset.originalText || 'Add to Cart';
    button.disabled = false;
    renderVariantSelector(document.body, product, async (selectedVariantId) => {
      await performAdd(selectedVariantId, button, quizSessionId);
    });
  } catch {
    button.textContent = 'Error';
    button.disabled = false;
  }
}

async function performAdd(variantId, button, quizSessionId) {
  const originalText = button.textContent;
  button.textContent = 'Adding...';
  button.disabled = true;
  try {
    await addToCart({ variantId, quantity: 1 });
    button.textContent = 'Added ✓';
    button.style.backgroundColor = '#008060';
    await refreshCartCount();
    openCartDrawer();
    // Track analytics
    trackEvent('add_to_cart', quizSessionId, { variantId });
    setTimeout(() => {
      button.textContent = originalText;
      button.style.backgroundColor = '';
      button.disabled = false;
    }, 2000);
  } catch (error) {
    button.textContent = 'Failed — retry';
    button.disabled = false;
    setTimeout(() => { button.textContent = originalText; }, 3000);
  }
}
```

---

## SELF-VALIDATION CHECKLIST

- [ ] Cart AJAX calls use `/cart/add.js` (not GraphQL on storefront)
- [ ] Variant selector shown when product has multiple variants
- [ ] Sold-out variants disabled in selector
- [ ] `_quiz_source: "quizsnap"` property added for attribution
- [ ] Cart count refreshed after add
- [ ] Cart drawer opened after successful add
- [ ] Error state shown with retry option
- [ ] `buy_now` immediately redirects to `/checkout`

---

## NEVER

- Never call Shopify Admin API for cart operations (use AJAX API on storefront)
- Never skip variant selector for products with multiple variants
- Never add sold-out variants to cart
- Never redirect to checkout without confirming cart add succeeded

