```tsx
// app/routes/app.integrations.tsx
import { json, type LoaderFunctionArgs, type ActionFunctionArgs } from "@shopify/shopify-app-react-router";
import { useLoaderData, useActionData, useSubmit, useNavigation } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import {
  Page, Layout, Card, BlockStack, Text, TextField, Button,
  Select, Badge, InlineStack, Toast, Frame, Divider, Banner, Checkbox
} from "@shopify/polaris";
import { useState, useEffect, useCallback } from "react";

const PROVIDERS = [
  { label: "Klaviyo", value: "klaviyo", docsUrl: "https://developers.klaviyo.com" },
  { label: "Mailchimp", value: "mailchimp", docsUrl: "https://mailchimp.com/developer" },
  { label: "Omnisend", value: "omnisend", docsUrl: "https://api-docs.omnisend.com" },
];

export async function loader({ request }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const integration = await db.emailIntegration.findUnique({ where: { shop: session.shop } });
  return json({ integration });
}

export async function action({ request }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const intent = formData.get("intent") as string;
  const shop = session.shop;

  try {
    switch (intent) {
      case "connect": {
        const provider = formData.get("provider") as string;
        const apiKey = formData.get("apiKey") as string;
        const listId = formData.get("listId") as string || null;
        const syncTags = formData.get("syncTags") === "true";

        if (!["klaviyo", "mailchimp", "omnisend"].includes(provider)) {
          return json({ error: "Invalid provider" }, { status: 400 });
        }
        if (!apiKey || apiKey.length < 10) {
          return json({ error: "Invalid API key" }, { status: 400 });
        }

        // Test the API key before saving
        const testResult = await testApiKey(provider, apiKey, listId);
        if (!testResult.success) {
          return json({ error: `API key test failed: ${testResult.error}` }, { status: 400 });
        }

        await db.emailIntegration.upsert({
          where: { shop },
          update: { provider, apiKey, listId, listName: testResult.listName, syncTags, enabled: true },
          create: { shop, provider, apiKey, listId, listName: testResult.listName, syncTags, enabled: true },
        });
        return json({ success: true, message: `${provider} connected successfully` });
      }
      case "disconnect": {
        await db.emailIntegration.deleteMany({ where: { shop } });
        return json({ success: true, message: "Integration disconnected" });
      }
      case "toggle": {
        const integration = await db.emailIntegration.findUnique({ where: { shop } });
        if (!integration) return json({ error: "No integration found" }, { status: 404 });
        await db.emailIntegration.update({
          where: { shop },
          data: { enabled: !integration.enabled },
        });
        return json({ success: true, message: integration.enabled ? "Integration paused" : "Integration resumed" });
      }
      default:
        return json({ error: "Unknown action" }, { status: 400 });
    }
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : "An error occurred" }, { status: 500 });
  }
}
```

