    const list = listId ? data.data?.find((l: any) => l.id === listId) : data.data?.[0];
    return { success: true, listName: list?.attributes?.name ?? "Default List" };
  } catch {
    return { success: false, error: "Failed to connect to Klaviyo" };
  }
}

async function testMailchimpKey(apiKey: string, listId?: string | null): Promise<TestResult> {
  try {
    // Extract datacenter from API key (format: key-dc)
    const dc = apiKey.split("-").pop();
    const response = await fetch(`https://${dc}.api.mailchimp.com/3.0/ping`, {
      headers: { "Authorization": `apikey ${apiKey}` },
    });
    if (!response.ok) return { success: false, error: "Invalid Mailchimp API key" };
    return { success: true, listName: "Mailchimp Audience" };
  } catch {
    return { success: false, error: "Failed to connect to Mailchimp" };
  }
}

async function testOmnisendKey(apiKey: string): Promise<TestResult> {
  try {
    const response = await fetch("https://api.omnisend.com/v3/contacts?limit=1", {
      headers: { "X-API-KEY": apiKey },
    });
    if (!response.ok) return { success: false, error: "Invalid Omnisend API key" };
    return { success: true, listName: "Omnisend Contacts" };
  } catch {
    return { success: false, error: "Failed to connect to Omnisend" };
  }
}
```

---

## SYNC ON QUIZ COMPLETION

```typescript
// app/services/email.server.ts — syncEmailOnCompletion()
export async function syncEmailOnCompletion(
  shop: string,
  email: string,
  quizTitle: string,
  tags: string[],
  personalityType: string | null,
  quizId: string
): Promise<void> {
  const integration = await db.emailIntegration.findUnique({
    where: { shop },
    select: { provider: true, apiKey: true, listId: true, enabled: true, syncTags: true, tagPrefix: true },
  });

  if (!integration || !integration.enabled) return;

  const contactProperties: Record<string, string> = {
    quiz_title: quizTitle,
    quiz_id: quizId,
    quiz_completed_at: new Date().toISOString(),
    ...(personalityType && { quiz_personality: personalityType }),
    ...(integration.syncTags && { quiz_tags: tags.join(", ") }),
  };

  switch (integration.provider) {
    case "klaviyo":
      await syncToKlaviyo(integration.apiKey, integration.listId, email, contactProperties, tags, integration.tagPrefix);
      break;
    case "mailchimp":
      await syncToMailchimp(integration.apiKey, integration.listId, email, contactProperties);
      break;
    case "omnisend":
      await syncToOmnisend(integration.apiKey, email, contactProperties, tags);
      break;
  }

  await db.emailIntegration.update({
    where: { shop },
    data: { lastSyncAt: new Date() },
  });
}

async function syncToKlaviyo(
  apiKey: string, listId: string | null, email: string,
  properties: Record<string, string>, tags: string[], tagPrefix: string
): Promise<void> {
  // Create/update profile
  await fetch("https://a.klaviyo.com/api/profiles/", {
    method: "POST",
    headers: {
      "Authorization": `Klaviyo-API-Key ${apiKey}`,
      "Content-Type": "application/json",
      "revision": "2024-10-15",
    },
    body: JSON.stringify({
      data: {
        type: "profile",
        attributes: {
          email,
          properties: {
            ...properties,
            ...Object.fromEntries(tags.map(t => [`${tagPrefix}${t}`, true])),
          },
        },
      },
    }),
  });

  // Add to list if configured
  if (listId) {
    const profileResponse = await fetch(`https://a.klaviyo.com/api/profiles/?filter=equals(email,"${encodeURIComponent(email)}")`, {
      headers: { "Authorization": `Klaviyo-API-Key ${apiKey}`, "revision": "2024-10-15" },
    });
    const profileData = await profileResponse.json();
    const profileId = profileData.data?.[0]?.id;
    if (profileId) {
      await fetch(`https://a.klaviyo.com/api/lists/${listId}/relationships/profiles/`, {
        method: "POST",
        headers: {
          "Authorization": `Klaviyo-API-Key ${apiKey}`,
          "Content-Type": "application/json",
          "revision": "2024-10-15",
        },
        body: JSON.stringify({ data: [{ type: "profile", id: profileId }] }),
      });
    }
  }
}
```

---

## SELF-VALIDATION CHECKLIST

- [ ] `EmailIntegration` uses `upsert` — safe to call connect multiple times
- [ ] API key tested before saving (never store invalid keys)
- [ ] `syncEmailOnCompletion()` silently fails — never crashes quiz submit
- [ ] Klaviyo uses API v3 (revision: 2024-10-15)
- [ ] Tags synced as contact properties with configurable prefix
- [ ] `enabled` flag checked before sync
- [ ] Integration scoped to shop — no cross-shop leakage
- [ ] `npm run typecheck` passes

---

## NEVER

- Never store API keys in plaintext without encryption (use env var or encrypted field)
- Never block quiz submission waiting for email sync — fire and forget
- Never sync PII to email providers without user's email question answer
- Never expose API keys in client-side code or API responses

