              type: "profile",
              attributes: { email: event.email },
            },
          },
          properties: event.properties,
        },
      },
    }),
  });

  if (!response.ok) {
    const error = await response.json();
    throw new Error(`Klaviyo event error: ${JSON.stringify(error.errors?.[0])}`);
  }
}

// ─── List Management ─────────────────────────────────────────────────────────

export async function addProfileToList(
  apiKey: string,
  listId: string,
  profileId: string
): Promise<void> {
  const response = await fetch(`${KLAVIYO_BASE}/lists/${listId}/relationships/profiles/`, {
    method: "POST",
    headers: klaviyoHeaders(apiKey),
    body: JSON.stringify({
      data: [{ type: "profile", id: profileId }],
    }),
  });

  if (!response.ok && response.status !== 204) {
    const error = await response.json();
    throw new Error(`Klaviyo list error: ${JSON.stringify(error.errors?.[0])}`);
  }
}

export async function getLists(apiKey: string): Promise<Array<{ id: string; name: string }>> {
  const response = await fetch(`${KLAVIYO_BASE}/lists/`, {
    headers: klaviyoHeaders(apiKey),
  });
  if (!response.ok) throw new Error("Failed to fetch Klaviyo lists");
  const data = await response.json();
  return (data.data ?? []).map((l: any) => ({ id: l.id, name: l.attributes.name }));
}

// ─── Quiz Completion Flow ────────────────────────────────────────────────────

export interface QuizCompletionData {
  email: string;
  quizTitle: string;
  quizId: string;
  tags: string[];
  personalityType: string | null;
  totalScore: number;
  tagPrefix: string;
  listId: string | null;
}

export async function syncQuizCompletionToKlaviyo(
  apiKey: string,
  data: QuizCompletionData
): Promise<void> {
  // Build custom properties from quiz data
  const customProperties: Record<string, string | boolean | number> = {
    quiz_title: data.quizTitle,
    quiz_id: data.quizId,
    quiz_completed_at: new Date().toISOString(),
    quiz_score: data.totalScore,
    quiz_tags: data.tags.join(", "),
    ...(data.personalityType && { quiz_personality: data.personalityType }),
    // Individual tag flags for segmentation
    ...Object.fromEntries(data.tags.map(t => [`${data.tagPrefix}${t}`, true])),
  };

  // 1. Upsert profile
  const profileId = await upsertKlaviyoProfile(apiKey, {
    email: data.email,
    customProperties,
  });

  // 2. Track "Quiz Completed" event
  await trackKlaviyoEvent(apiKey, {
    eventName: "Quiz Completed",
    email: data.email,
    properties: {
      quiz_title: data.quizTitle,
      quiz_id: data.quizId,
      recommended_tags: data.tags,
      personality_type: data.personalityType ?? "",
      score: data.totalScore,
    },
  });

  // 3. Add to list if configured
  if (data.listId && profileId) {
    await addProfileToList(apiKey, data.listId, profileId);
  }
}
```

---

## STANDARD QUIZ EVENTS TO TRACK

| Event Name | Trigger | Key Properties |
|-----------|---------|----------------|
| `Quiz Started` | User begins quiz | quiz_title, quiz_id |
| `Quiz Completed` | User sees results | quiz_title, tags, score, personality |
| `Product Clicked` | CTA clicked on result | product_title, product_id |
| `Add to Cart` | Product added from quiz | product_title, variant_id |
| `Order Placed` | Order with quiz attribution | order_id, order_total, quiz_id |

---

## FLOW TRIGGER SETUP (Klaviyo Dashboard)

After implementing, tell the merchant to:
1. Go to Klaviyo → Flows → Create Flow
2. Select "Metric" trigger → "Quiz Completed"
3. Add filter: `quiz_title = "[Your Quiz Name]"`
4. Add email step with dynamic block showing `{{ event.properties.recommended_tags }}`

---

## SELF-VALIDATION CHECKLIST

- [ ] API revision header `"revision": "2024-10-15"` on all requests
- [ ] `Authorization: Klaviyo-API-Key {key}` (not Bearer)
- [ ] Profile upsert handles 409 conflict by fetching existing ID
- [ ] Event tracking uses `/api/events/` not legacy `/api/track`
- [ ] Tag properties prefixed to avoid collisions (default: "quiz_")
- [ ] All Klaviyo calls wrapped in try/catch — never crash quiz submit
- [ ] `npm run typecheck` passes on klaviyo.server.ts

---

## NEVER

- Never use legacy Klaviyo v1/v2 endpoints (`/api/track`, `/api/identify`)
- Never block quiz submit waiting for Klaviyo sync — fire and forget
- Never log API keys even during debugging
- Never call Klaviyo from client-side code — always server-side

