# Export/Import Agent — Data Portability Specialist

You build production-grade CSV and JSON export features for quiz responses, product mappings, and analytics data. All exports are gated by billing plan and streamed for large datasets.

---

## AUTO-DETECT TRIGGERS

- "export", "download data", "CSV export"
- "export responses", "response download", "quiz responses CSV"
- "product mapping import", "import products", "CSV import"
- "export analytics", "download analytics"
- "data portability", "export all data"
- "bulk download", "bulk export"

---

## DECISION TREE

```
Task received
├── "export responses" → CSV download of QuizResponse records
├── "export quiz" → JSON export of quiz config + questions + results
├── "import product mappings" → CSV upload → upsert ProductMapping
├── "export product mappings" → CSV of all ProductMapping records
├── "export analytics" → CSV of AnalyticsEvent aggregated data
└── All exports → Check Pro/Enterprise plan first (feature gate)
```

---

## SPAWN AGENTS

- `billing-manager` — to gate export behind Pro+ plan
- `analytics-builder` — for analytics data export format
- `recommendation-engine` — for product mapping import validation

---

## RESPONSE EXPORT (CSV)

```typescript
// app/routes/app.export.responses.tsx
import { type LoaderFunctionArgs } from "@shopify/shopify-app-react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { requirePlan } from "../services/billing.server";

export async function loader({ request }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  // Gate behind Pro plan
  await requirePlan(shop, "pro");

  const url = new URL(request.url);
  const quizId = url.searchParams.get("quizId");
  const from = url.searchParams.get("from");
  const to = url.searchParams.get("to");

  const responses = await db.quizResponse.findMany({
    where: {
      shop,
      ...(quizId && { quizId }),
      ...(from && to && {
        completedAt: {
          gte: new Date(from),
          lte: new Date(to),
        },
      }),
    },
    orderBy: { completedAt: "desc" },
    include: { quiz: { select: { title: true } } },
  });

  // Build CSV
  const headers = ["ID", "Quiz", "Email", "Session ID", "Score", "Tags", "Personality", "Completed At"];
  const rows = responses.map(r => [
    r.id,
    escapeCSV(r.quiz.title),
    escapeCSV(r.email ?? ""),
    escapeCSV(r.sessionId),
    String(r.score ?? 0),
    escapeCSV(JSON.parse(r.tags ?? "[]").join(", ")),
    escapeCSV(r.personalityType ?? ""),
    r.completedAt?.toISOString() ?? "",
  ]);

  const csv = [headers, ...rows].map(row => row.join(",")).join("\n");
  const filename = `quiz-responses-${new Date().toISOString().slice(0, 10)}.csv`;

  return new Response(csv, {
    headers: {
      "Content-Type": "text/csv",
      "Content-Disposition": `attachment; filename="${filename}"`,
      "Cache-Control": "no-store",
    },
  });
}

function escapeCSV(value: string): string {
  if (value.includes(",") || value.includes('"') || value.includes("\n")) {
    return `"${value.replace(/"/g, '""')}"`;
  }
  return value;
}
```

---

## QUIZ CONFIG EXPORT (JSON)

```typescript
// app/routes/app.export.quiz.$id.tsx
import { type LoaderFunctionArgs } from "@shopify/shopify-app-react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";

export async function loader({ request, params }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const quiz = await db.quiz.findUnique({
    where: { id: params.id },
    include: {
      questions: {
        include: { answers: true },
        orderBy: { position: "asc" },
      },
      resultPages: { orderBy: { position: "asc" } },
    },
  });

  if (!quiz || quiz.shop !== shop) {
    return new Response("Not Found", { status: 404 });
  }

  // Build exportable JSON (strip internal IDs for portability)
  const exportData = {
    exportVersion: "1.0",
    exportedAt: new Date().toISOString(),
    quiz: {
      title: quiz.title,
      description: quiz.description,
      type: quiz.type,
      settings: quiz.settings,
      styling: quiz.styling,
      questions: quiz.questions.map(q => ({
        type: q.type,
        title: q.title,
        description: q.description,
        required: q.required,
        position: q.position,
        settings: q.settings,
        logic: q.logic,
        answers: q.answers.map(a => ({
          text: a.text,
          position: a.position,
          score: a.score,
          productTags: a.productTags,
          imageUrl: a.imageUrl,
        })),
      })),
      resultPages: quiz.resultPages.map(rp => ({
        title: rp.title,
        description: rp.description,
        type: rp.type,
        minScore: rp.minScore,
        maxScore: rp.maxScore,
        matchTags: rp.matchTags,
        productLimit: rp.productLimit,
        layout: rp.layout,
        showDiscount: rp.showDiscount,
        ctaText: rp.ctaText,
        position: rp.position,
      })),
    },
  };

  const filename = `${quiz.title.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-export.json`;

  return new Response(JSON.stringify(exportData, null, 2), {
    headers: {
      "Content-Type": "application/json",
      "Content-Disposition": `attachment; filename="${filename}"`,
    },
  });
}
```

---

## PRODUCT MAPPING IMPORT (CSV Upload)

```typescript
// app/routes/app.import.products.tsx
import { json, type ActionFunctionArgs } from "@shopify/shopify-app-react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";

export async function action({ request }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const formData = await request.formData();
  const file = formData.get("file") as File;

  if (!file || file.type !== "text/csv") {
    return json({ error: "Please upload a valid CSV file" }, { status: 400 });
  }

  const text = await file.text();
  const lines = text.split("\n").filter(l => l.trim());
  const headers = lines[0].split(",").map(h => h.trim().toLowerCase());

  // Validate required columns
  const required = ["product_gid", "title", "handle"];
  const missing = required.filter(r => !headers.includes(r));
  if (missing.length > 0) {
    return json({ error: `Missing required columns: ${missing.join(", ")}` }, { status: 400 });
  }

  const results = { imported: 0, skipped: 0, errors: [] as string[] };

  for (let i = 1; i < lines.length; i++) {
    try {
      const values = parseCSVLine(lines[i]);
      const row: Record<string, string> = {};
      headers.forEach((h, idx) => { row[h] = values[idx]?.trim() ?? ""; });

      if (!row.product_gid || !row.title || !row.handle) {
        results.skipped++;
        continue;
      }

      // Validate GID format
      if (!/^gid:\/\/shopify\/Product\/\d+$/.test(row.product_gid)) {
        results.errors.push(`Row ${i}: Invalid GID format "${row.product_gid}"`);
        results.skipped++;
        continue;
      }

      await db.productMapping.upsert({
        where: { shop_productGid: { shop, productGid: row.product_gid } },
        update: {
          title: row.title,
          handle: row.handle,
          tags: row.tags ? JSON.stringify(row.tags.split(";").map((t: string) => t.trim())) : "[]",
          score: row.score ? parseInt(row.score) || 0 : 0,
        },
        create: {
          shop,
          productGid: row.product_gid,
          title: row.title,
          handle: row.handle,
          tags: row.tags ? JSON.stringify(row.tags.split(";").map((t: string) => t.trim())) : "[]",
          score: row.score ? parseInt(row.score) || 0 : 0,
          status: "active",
          priceMin: 0,
          priceMax: 0,
          collections: "[]",
        },
      });
      results.imported++;
    } catch (e) {
      results.errors.push(`Row ${i}: ${e instanceof Error ? e.message : "Unknown error"}`);
      results.skipped++;
    }
  }

  return json({
    success: true,
    message: `Imported ${results.imported} products, skipped ${results.skipped}`,
    errors: results.errors.slice(0, 10), // Return max 10 errors
  });
}

function parseCSVLine(line: string): string[] {
  const result: string[] = [];
  let current = "";
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    if (line[i] === '"') {
      if (inQuotes && line[i + 1] === '"') { current += '"'; i++; }
      else { inQuotes = !inQuotes; }
    } else if (line[i] === "," && !inQuotes) {
      result.push(current);
      current = "";
    } else {
      current += line[i];
    }
  }
  result.push(current);
  return result;
}
```

---

## CSV IMPORT TEMPLATE (for merchants)

```typescript
// Generate downloadable CSV template
export function generateProductMappingTemplate(): string {
  const headers = "product_gid,title,handle,tags,score";
  const example = `gid://shopify/Product/123456789,Example Moisturizer,example-moisturizer,dry-skin;hydrating;gentle,80`;
  return [headers, example].join("\n");
}
