## RESPONSE EXPORT (CSV)

```typescript
// app/routes/app.export.responses.tsx
import { type LoaderFunctionArgs } from "@shopify/shopify-app-react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { requirePlan } from "../services/billing.server";

export async function loader({ request }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  // Gate behind Pro plan
  await requirePlan(shop, "pro");

  const url = new URL(request.url);
  const quizId = url.searchParams.get("quizId");
  const from = url.searchParams.get("from");
  const to = url.searchParams.get("to");

  const responses = await db.quizResponse.findMany({
    where: {
      shop,
      ...(quizId && { quizId }),
      ...(from && to && {
        completedAt: {
          gte: new Date(from),
          lte: new Date(to),
        },
      }),
    },
    orderBy: { completedAt: "desc" },
    include: { quiz: { select: { title: true } } },
  });

  // Build CSV
  const headers = ["ID", "Quiz", "Email", "Session ID", "Score", "Tags", "Personality", "Completed At"];
  const rows = responses.map(r => [
    r.id,
    escapeCSV(r.quiz.title),
    escapeCSV(r.email ?? ""),
    escapeCSV(r.sessionId),
    String(r.score ?? 0),
    escapeCSV(JSON.parse(r.tags ?? "[]").join(", ")),
    escapeCSV(r.personalityType ?? ""),
    r.completedAt?.toISOString() ?? "",
  ]);

  const csv = [headers, ...rows].map(row => row.join(",")).join("\n");
  const filename = `quiz-responses-${new Date().toISOString().slice(0, 10)}.csv`;

  return new Response(csv, {
    headers: {
      "Content-Type": "text/csv",
      "Content-Disposition": `attachment; filename="${filename}"`,
      "Cache-Control": "no-store",
    },
  });
}

function escapeCSV(value: string): string {
  if (value.includes(",") || value.includes('"') || value.includes("\n")) {
    return `"${value.replace(/"/g, '""')}"`;
  }
  return value;
}
```

