## PRODUCT MAPPING IMPORT (CSV Upload)

```typescript
// app/routes/app.import.products.tsx
import { json, type ActionFunctionArgs } from "@shopify/shopify-app-react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";

export async function action({ request }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const formData = await request.formData();
  const file = formData.get("file") as File;

  if (!file || file.type !== "text/csv") {
    return json({ error: "Please upload a valid CSV file" }, { status: 400 });
  }

  const text = await file.text();
  const lines = text.split("\n").filter(l => l.trim());
  const headers = lines[0].split(",").map(h => h.trim().toLowerCase());

  // Validate required columns
  const required = ["product_gid", "title", "handle"];
  const missing = required.filter(r => !headers.includes(r));
  if (missing.length > 0) {
    return json({ error: `Missing required columns: ${missing.join(", ")}` }, { status: 400 });
  }

  const results = { imported: 0, skipped: 0, errors: [] as string[] };

  for (let i = 1; i < lines.length; i++) {
    try {
      const values = parseCSVLine(lines[i]);
      const row: Record<string, string> = {};
      headers.forEach((h, idx) => { row[h] = values[idx]?.trim() ?? ""; });

      if (!row.product_gid || !row.title || !row.handle) {
        results.skipped++;
        continue;
      }

      // Validate GID format
      if (!/^gid:\/\/shopify\/Product\/\d+$/.test(row.product_gid)) {
        results.errors.push(`Row ${i}: Invalid GID format "${row.product_gid}"`);
        results.skipped++;
        continue;
      }

      await db.productMapping.upsert({
        where: { shop_productGid: { shop, productGid: row.product_gid } },
        update: {
          title: row.title,
          handle: row.handle,
          tags: row.tags ? JSON.stringify(row.tags.split(";").map((t: string) => t.trim())) : "[]",
          score: row.score ? parseInt(row.score) || 0 : 0,
        },
        create: {
          shop,
          productGid: row.product_gid,
          title: row.title,
          handle: row.handle,
          tags: row.tags ? JSON.stringify(row.tags.split(";").map((t: string) => t.trim())) : "[]",
          score: row.score ? parseInt(row.score) || 0 : 0,
          status: "active",
          priceMin: 0,
          priceMax: 0,
          collections: "[]",
        },
      });
      results.imported++;
    } catch (e) {
      results.errors.push(`Row ${i}: ${e instanceof Error ? e.message : "Unknown error"}`);
      results.skipped++;
    }
  }

  return json({
    success: true,
    message: `Imported ${results.imported} products, skipped ${results.skipped}`,
    errors: results.errors.slice(0, 10), // Return max 10 errors
  });
}

function parseCSVLine(line: string): string[] {
  const result: string[] = [];
  let current = "";
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    if (line[i] === '"') {
      if (inQuotes && line[i + 1] === '"') { current += '"'; i++; }
      else { inQuotes = !inQuotes; }
    } else if (line[i] === "," && !inQuotes) {
      result.push(current);
      current = "";
    } else {
      current += line[i];
    }
  }
  result.push(current);
  return result;
}
```

