# Upsell Builder — Post-Quiz Revenue Maximization

## AUTO-DETECT TRIGGERS
- User mentions: upsell, cross-sell, bundle, complementary products, also buy
- Quiz result page needs to show additional products beyond primary recommendations
- Bundle discount offer below main product recommendations
- "Complete the set" feature for collection-based products

## DECISION TREE
```
Need upsell/cross-sell? →
  Extra products to recommend? → Upsell algorithm (high-scored, not already shown)
  Same collection pairing? → Cross-sell by shared collection membership
  Bundle offer? → Group 2-3 products with bundle discount
  "Complete the set"? → Filter same collection, exclude recommended
  Add all to cart? → Bundle add-to-cart endpoint
```

## UPSELL ALGORITHM

```typescript
// app/utils/upsell-algorithm.server.ts
import { db } from "~/db.server";

interface ProductScore {
  productId: string;
  score: number;
  title: string;
  price: number;
  imageUrl?: string;
  collectionIds: string[];
}

interface UpsellResult {
  type: "upsell" | "cross-sell" | "bundle";
  products: Array<{
    id: string;
    title: string;
    price: string;
    imageUrl?: string;
    reason: string;
  }>;
  bundleDiscount?: number;     // e.g. 0.10 = 10% off bundle
  bundleTitle?: string;
}

export async function computeUpsells(
  shop: string,
  primaryProductIds: string[],
  allProductScores: ProductScore[],
  options: {
    maxUpsells?: number;
    bundleDiscountPct?: number;
    enableCrossSell?: boolean;
  } = {}
): Promise<UpsellResult[]> {
  const {
    maxUpsells = 3,
    bundleDiscountPct = 0.10,
    enableCrossSell = true
  } = options;

  const primarySet = new Set(primaryProductIds);
  const results: UpsellResult[] = [];

  // 1. Upsell: High-scored products NOT in primary recommendations
  const upsellCandidates = allProductScores
    .filter(p => !primarySet.has(p.productId) && p.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, maxUpsells);

  if (upsellCandidates.length > 0) {
    results.push({
      type: "upsell",
      products: upsellCandidates.map(p => ({
        id: p.productId,
        title: p.title,
        price: p.price.toFixed(2),
        imageUrl: p.imageUrl,
        reason: "Also matches your profile",
      })),
    });
  }

  // 2. Cross-sell: Products from shared collections
  if (enableCrossSell && primaryProductIds.length > 0) {
    const primaryCollections = new Set(
      allProductScores
        .filter(p => primarySet.has(p.productId))
        .flatMap(p => p.collectionIds)
    );

    const crossSellCandidates = allProductScores
      .filter(p =>
        !primarySet.has(p.productId) &&
        !upsellCandidates.some(u => u.productId === p.productId) &&
        p.collectionIds.some(c => primaryCollections.has(c))
      )
      .slice(0, 2);

    if (crossSellCandidates.length > 0) {
      results.push({
        type: "cross-sell",
        products: crossSellCandidates.map(p => ({
          id: p.productId,
          title: p.title,
          price: p.price.toFixed(2),
          imageUrl: p.imageUrl,
          reason: "Frequently paired together",
        })),
      });
    }
  }

  // 3. Bundle: Top primary + top upsell with discount
  if (primaryProductIds.length >= 1 && upsellCandidates.length >= 1 && bundleDiscountPct > 0) {
    const bundleProducts = [
      ...allProductScores.filter(p => p.productId === primaryProductIds[0]),
      upsellCandidates[0],
    ];

    if (bundleProducts.length >= 2) {
      const totalPrice = bundleProducts.reduce((s, p) => s + p.price, 0);
      const discountedPrice = totalPrice * (1 - bundleDiscountPct);

      results.push({
        type: "bundle",
        products: bundleProducts.map(p => ({
          id: p.productId,
          title: p.title,
          price: p.price.toFixed(2),
          imageUrl: p.imageUrl,
          reason: "Bundle deal",
        })),
        bundleDiscount: bundleDiscountPct,
        bundleTitle: `Bundle & Save ${Math.round(bundleDiscountPct * 100)}%`,
      });
    }
  }

  return results;
}
```

## UPSELL BANNER COMPONENT (Storefront)

```typescript
// app/components/storefront/UpsellBanner.tsx
import { useState } from "react";

interface UpsellProduct {
  id: string;
  title: string;
  price: string;
  imageUrl?: string;
  reason: string;
}

interface Props {
  type: "upsell" | "cross-sell" | "bundle";
  products: UpsellProduct[];
  bundleDiscount?: number;
  bundleTitle?: string;
  storeDomain: string;
  onAddBundle?: (productIds: string[]) => Promise<void>;
}

export function UpsellBanner({ type, products, bundleDiscount, bundleTitle, storeDomain, onAddBundle }: Props) {
  const [addingBundle, setAddingBundle] = useState(false);
  const [bundleAdded, setBundleAdded] = useState(false);

  const sectionTitle = type === "bundle"
    ? bundleTitle ?? "Bundle & Save"
    : type === "cross-sell"
    ? "Frequently Paired Together"
    : "You Might Also Like";

  const totalBundlePrice = products.reduce((s, p) => s + parseFloat(p.price), 0);
  const discountedBundlePrice = bundleDiscount
    ? totalBundlePrice * (1 - bundleDiscount)
    : totalBundlePrice;

  async function handleAddBundle() {
    if (!onAddBundle) return;
    setAddingBundle(true);
    try {
      await onAddBundle(products.map(p => p.id));
      setBundleAdded(true);
      setTimeout(() => setBundleAdded(false), 3000);
    } finally {
      setAddingBundle(false);
    }
  }

  return (
    <div style={{
      border: "1.5px solid #e1e3e5",
      borderRadius: 8,
      padding: "16px 20px",
      marginTop: 24,
      background: type === "bundle" ? "#f9fafb" : "white",
    }}>
      <h3 style={{ margin: "0 0 12px", fontSize: 15, fontWeight: 600, color: "#202223" }}>
        {sectionTitle}
        {bundleDiscount && (
          <span style={{ marginLeft: 8, background: "#00A651", color: "white", borderRadius: 12, padding: "2px 8px", fontSize: 12 }}>
            {Math.round(bundleDiscount * 100)}% OFF
          </span>
        )}
      </h3>

      <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
        {products.map((product, i) => (
          <div key={product.id} style={{ display: "flex", alignItems: "center", gap: 8 }}>
            {i > 0 && <span style={{ color: "#6d7175", fontSize: 18 }}>+</span>}
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              {product.imageUrl && (
                <img src={product.imageUrl} alt={product.title} width={48} height={48}
                  style={{ borderRadius: 4, objectFit: "cover" }} />
              )}
              <div>
                <p style={{ margin: 0, fontSize: 13, fontWeight: 500 }}>{product.title}</p>
                <p style={{ margin: 0, fontSize: 13, color: "#6d7175" }}>${product.price}</p>
              </div>
            </div>
          </div>
        ))}
      </div>

      {type === "bundle" && bundleDiscount && (
        <div style={{ marginTop: 12, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div>
            <span style={{ textDecoration: "line-through", color: "#6d7175", fontSize: 14 }}>
              ${totalBundlePrice.toFixed(2)}
            </span>
            {" "}
            <span style={{ fontWeight: 700, fontSize: 16, color: "#202223" }}>
              ${discountedBundlePrice.toFixed(2)}
            </span>
