// app/services/segments.server.ts
interface SegmentRule {
  type: "tag" | "personality" | "score_range" | "quiz_completed";
  value: string;
  quizId?: string;
  minScore?: number;
  maxScore?: number;
}

export async function getSegmentCustomers(
  shop: string,
  rules: SegmentRule[]
): Promise<Array<{ email: string; sessionId: string; completedAt: Date; tags: string[] }>> {
  const responses = await db.quizResponse.findMany({
    where: { shop, email: { not: null } },
    select: { email: true, sessionId: true, completedAt: true, tags: true, personalityType: true, score: true, quizId: true },
    orderBy: { completedAt: "desc" },
  });

  return responses.filter(r => {
    const responseTags = JSON.parse(r.tags ?? "[]") as string[];
    return rules.every(rule => {
      switch (rule.type) {
        case "tag":
          return responseTags.some(t => t.toLowerCase() === rule.value.toLowerCase());
        case "personality":
          return r.personalityType?.toLowerCase() === rule.value.toLowerCase();
        case "score_range":
          return (r.score ?? 0) >= (rule.minScore ?? 0) && (r.score ?? 0) <= (rule.maxScore ?? 100);
        case "quiz_completed":
          return !rule.quizId || r.quizId === rule.quizId;
        default:
          return true;
      }
    });
  }).map(r => ({
    email: r.email!,
    sessionId: r.sessionId,
    completedAt: r.completedAt!,
    tags: JSON.parse(r.tags ?? "[]"),
  }));
}

export async function countSegmentMembers(shop: string, rules: SegmentRule[]): Promise<number> {
  const members = await getSegmentCustomers(shop, rules);
  return members.length;
}
