// app/services/trial.server.ts
import db from "../db.server";

const TRIAL_DAYS = 14;

export async function startTrial(shop: string): Promise<void> {
  const trialEndsAt = new Date(Date.now() + TRIAL_DAYS * 24 * 60 * 60 * 1000);
  await db.subscription.upsert({
    where: { shop },
    update: {}, // Never reset existing subscription
    create: {
      shop,
      plan: "free",
      status: "trialing",
      trialEndsAt,
      trialDays: TRIAL_DAYS,
    },
  });
}

export async function getTrialStatus(shop: string): Promise<{
  status: "active" | "expiring_soon" | "expired" | "converted";
  daysRemaining: number;
  trialEndsAt: Date | null;
}> {
  const sub = await db.subscription.findUnique({ where: { shop } });
  if (!sub) return { status: "active", daysRemaining: TRIAL_DAYS, trialEndsAt: null };
  if (sub.status !== "trialing") return { status: "converted", daysRemaining: 0, trialEndsAt: null };

  const now = new Date();
  const daysRemaining = sub.trialEndsAt
    ? Math.max(0, Math.ceil((sub.trialEndsAt.getTime() - now.getTime()) / (1000 * 60 * 60 * 24)))
    : TRIAL_DAYS;

  if (daysRemaining === 0) return { status: "expired", daysRemaining: 0, trialEndsAt: sub.trialEndsAt };
  if (daysRemaining <= 3) return { status: "expiring_soon", daysRemaining, trialEndsAt: sub.trialEndsAt };
  return { status: "active", daysRemaining, trialEndsAt: sub.trialEndsAt };
}

export async function checkAndExpireTrial(shop: string): Promise<boolean> {
  const sub = await db.subscription.findUnique({ where: { shop } });
  if (!sub || sub.status !== "trialing" || !sub.trialEndsAt) return false;

  if (new Date() > sub.trialEndsAt) {
    await db.subscription.update({
      where: { shop },
      data: { status: "trial_expired" },
    });
    return true; // Was expired
  }
  return false;
}
