// app/services/billing.server.ts — PLAN LIMITS (canonical)
export const PLAN_LIMITS = {
  free:       { quizzes: 1,  responses: 100,   features: ["basic"] },
  starter:    { quizzes: 5,  responses: 1000,  features: ["basic", "email"] },
  pro:        { quizzes: -1, responses: 10000, features: ["basic", "email", "analytics", "export", "ab_testing"] },
  enterprise: { quizzes: -1, responses: -1,    features: ["all"] },
} as const;

export async function checkUsageLimit(
  shop: string,
  resource: "quizzes" | "responses"
): Promise<{ allowed: boolean; current: number; limit: number; plan: string }> {
  const sub = await db.subscription.findUnique({
    where: { shop },
    select: { plan: true, monthlyResponses: true, responseResetAt: true },
  });

  const plan = (sub?.plan ?? "free") as keyof typeof PLAN_LIMITS;
  const limits = PLAN_LIMITS[plan];

  if (resource === "responses") {
    // Reset monthly counter if needed
    await resetMonthlyCounterIfNeeded(shop, sub);
    const current = sub?.monthlyResponses ?? 0;
    const limit = limits.responses;
    if (limit === -1) return { allowed: true, current, limit: Infinity, plan };
    return { allowed: current < limit, current, limit, plan };
  }

  if (resource === "quizzes") {
    const current = await db.quiz.count({ where: { shop, status: { not: "archived" } } });
    const limit = limits.quizzes;
    if (limit === -1) return { allowed: true, current, limit: Infinity, plan };
    return { allowed: current < limit, current, limit, plan };
  }

  return { allowed: false, current: 0, limit: 0, plan };
}

async function resetMonthlyCounterIfNeeded(shop: string, sub: any): Promise<void> {
  if (!sub?.responseResetAt) return;
  const now = new Date();
  if (now >= sub.responseResetAt) {
    const nextReset = new Date(now.getFullYear(), now.getMonth() + 1, 1);
    await db.subscription.update({
      where: { shop },
      data: { monthlyResponses: 0, responseResetAt: nextReset },
    });
  }
}

export async function incrementResponseCount(shop: string): Promise<void> {
  await db.subscription.upsert({
    where: { shop },
    update: { monthlyResponses: { increment: 1 } },
    create: {
      shop,
      plan: "free",
      status: "active",
      monthlyResponses: 1,
      responseResetAt: new Date(new Date().getFullYear(), new Date().getMonth() + 1, 1),
    },
  });
}
