  let settings: Record<string, unknown> = {};
  let styling: Record<string, string> = {};
  try { settings = JSON.parse(quiz.settings); } catch {}
  try { styling = JSON.parse(quiz.styling); } catch {}

  return json({ quiz: { ...quiz, settings, styling }, shop });
}

