## HEALTH CHECK IMPLEMENTATION

```typescript
// app/routes/health.tsx — Public health check endpoint
import { json, type LoaderFunctionArgs } from "react-router";
import db from "../db.server";

export async function loader({ request }: LoaderFunctionArgs) {
  const startTime = Date.now();
  const checks: Record<string, { status: "ok" | "fail"; latencyMs?: number; error?: string }> = {};

  // 1. Database check
  try {
    const dbStart = Date.now();
    await db.$queryRaw`SELECT 1`;
    checks.database = { status: "ok", latencyMs: Date.now() - dbStart };
  } catch (e) {
    checks.database = { status: "fail", error: "Database unreachable" };
  }

  // 2. Environment variables check
  const requiredVars = ["SHOPIFY_API_KEY", "SHOPIFY_API_SECRET", "DATABASE_URL", "SHOPIFY_APP_URL"];
  const missingVars = requiredVars.filter(v => !process.env[v]);
  checks.environment = missingVars.length === 0
    ? { status: "ok" }
    : { status: "fail", error: `Missing: ${missingVars.join(", ")}` };

  // Overall status
  const allOk = Object.values(checks).every(c => c.status === "ok");
  const totalLatency = Date.now() - startTime;

  return json(
    {
      status: allOk ? "ok" : "degraded",
      timestamp: new Date().toISOString(),
      version: process.env.npm_package_version ?? "unknown",
      latencyMs: totalLatency,
      checks,
    },
    { status: allOk ? 200 : 503 }
  );
}
