```javascript
// extensions/quiz-widget/assets/session.js

const STORAGE_KEY_PREFIX = "quizsnap_";
const SESSION_TTL = 24 * 60 * 60 * 1000; // 24 hours

export function saveQuizProgress(quizSlug, state) {
  const data = {
    quizSlug,
    currentIndex: state.currentIndex,
    answers: state.answers,
    sessionId: state.sessionId,
    savedAt: Date.now(),
  };
  try {
    sessionStorage.setItem(`${STORAGE_KEY_PREFIX}progress_${quizSlug}`, JSON.stringify(data));
  } catch {
    // sessionStorage might be full or unavailable
  }
}

export function loadQuizProgress(quizSlug) {
  try {
    const raw = sessionStorage.getItem(`${STORAGE_KEY_PREFIX}progress_${quizSlug}`);
    if (!raw) return null;
    const data = JSON.parse(raw);
    // Expire after TTL
    if (Date.now() - data.savedAt > SESSION_TTL) {
      clearQuizProgress(quizSlug);
      return null;
    }
    return data;
  } catch {
    return null;
  }
}

export function clearQuizProgress(quizSlug) {
  try {
    sessionStorage.removeItem(`${STORAGE_KEY_PREFIX}progress_${quizSlug}`);
  } catch {}
}

export function saveRecentCompletion(quizSlug, resultTitle) {
  try {
    const key = `${STORAGE_KEY_PREFIX}recent`;
    const existing = JSON.parse(localStorage.getItem(key) ?? "[]");
    const updated = [
      { quizSlug, resultTitle, completedAt: Date.now() },
      ...existing.filter(r => r.quizSlug !== quizSlug),
    ].slice(0, 5); // Keep last 5
    localStorage.setItem(key, JSON.stringify(updated));
  } catch {}
}

export function hasInProgressQuiz(quizSlug) {
  const progress = loadQuizProgress(quizSlug);
  return progress !== null && progress.currentIndex > 0;
}

// Show "Resume Quiz" button if progress exists
export function maybeShowResumePrompt(container, quizSlug, onResume, onRestart) {
  if (!hasInProgressQuiz(quizSlug)) return;

  const prompt = document.createElement("div");
  prompt.className = "qs-resume-prompt";
  prompt.innerHTML = `
    <p class="qs-resume-text">You started this quiz before. Continue where you left off?</p>
    <div class="qs-resume-actions">
      <button class="qs-resume-continue">Continue Quiz</button>
      <button class="qs-resume-restart">Start Over</button>
    </div>
  `;

  prompt.querySelector(".qs-resume-continue").addEventListener("click", () => {
    prompt.remove();
    onResume(loadQuizProgress(quizSlug));
  });
  prompt.querySelector(".qs-resume-restart").addEventListener("click", () => {
    clearQuizProgress(quizSlug);
    prompt.remove();
    onRestart();
  });

  container.prepend(prompt);
}
```

