## COLLECTION SYNC QUERY

```typescript
// app/services/collections.server.ts
const COLLECTIONS_QUERY = `#graphql
  query getCollections($first: Int!, $after: String) {
    collections(first: $first, after: $after) {
      edges {
        node {
          id
          title
          handle
          updatedAt
          productsCount { count }
        }
      }
      pageInfo { hasNextPage endCursor }
    }
  }
`;

export interface ShopifyCollection {
  id: string;
  title: string;
  handle: string;
  productCount: number;
}

export async function syncCollections(admin: any): Promise<ShopifyCollection[]> {
  const collections: ShopifyCollection[] = [];
  let cursor: string | null = null;

  do {
    const response = await admin.graphql(COLLECTIONS_QUERY, {
      variables: { first: 250, after: cursor },
    });
    const { data } = await response.json();
    const { edges, pageInfo } = data.collections;

    for (const { node } of edges) {
      collections.push({
        id: node.id,
        title: node.title,
        handle: node.handle,
        productCount: node.productsCount?.count ?? 0,
      });
    }
    cursor = pageInfo.hasNextPage ? pageInfo.endCursor : null;
  } while (cursor);

  return collections;
}

// Collection picker for result page settings
export async function getCollectionsForShop(admin: any): Promise<ShopifyCollection[]> {
  return syncCollections(admin);
}
```

