  requiredCollectionGids: string[]
): ScoredProduct[] {
  if (!requiredCollectionGids.length) return scored; // No filter = all products

  return scored.filter(product => {
    const mapping = productMappings.find(m => m.productGid === product.productGid);
    if (!mapping) return false;
    let productCollections: string[] = [];
    try { productCollections = JSON.parse(mapping.collections); } catch {}
    return requiredCollectionGids.some(c => productCollections.includes(c));
  });
}
