```
Task received
├── "generate on completion" → Create unique discount code via GraphQL mutation
├── "discount reveal UI" → Show code with copy button on result page
├── "percentage discount" → discountCodeBasicCreate with PERCENTAGE
├── "fixed amount" → discountCodeBasicCreate with FIXED_AMOUNT
├── "free shipping" → discountCodeFreeShippingCreate
└── After creation → Display in result page + track analytics event
```

---

## SPAWN AGENTS

- `results-builder` — to add discount reveal section to result page
- `analytics-builder` — to track discount_revealed and discount_used events
- `billing-manager` — discount reveal is a Pro+ feature

---

## DISCOUNT CREATION VIA ADMIN GRAPHQL

```typescript
// app/services/discount.server.ts
import type { AdminApiContext } from "@shopify/shopify-app-react-router";

interface DiscountConfig {
  type: "percentage" | "fixed_amount" | "free_shipping";
  value: number;
  title: string;
  usageLimit?: number;
  expiresAt?: Date;
  prefix?: string;
  minimumAmount?: number;
}

// Generate unique code with retry on collision
function generateCode(prefix: string = "QUIZ"): string {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"; // Removed ambiguous chars
  let code = `${prefix}-`;
  for (let i = 0; i < 8; i++) {
    code += chars[Math.floor(Math.random() * chars.length)];
  }
  return code;
}

export async function generateDiscountCode(
  admin: AdminApiContext["admin"],
  config: DiscountConfig
): Promise<string | null> {
  const code = generateCode(config.prefix ?? "QUIZ");

  try {
    if (config.type === "percentage") {
      return await createPercentageDiscount(admin, code, config);
    } else if (config.type === "fixed_amount") {
      return await createFixedDiscount(admin, code, config);
    } else if (config.type === "free_shipping") {
      return await createFreeShippingDiscount(admin, code, config);
    }
  } catch (e) {
    console.error("Discount creation failed:", e);
  }

  return null;
}

async function createPercentageDiscount(admin: any, code: string, config: DiscountConfig): Promise<string | null> {
  const mutation = `#graphql
    mutation discountCodeBasicCreate($basicCodeDiscount: DiscountCodeBasicInput!) {
      discountCodeBasicCreate(basicCodeDiscount: $basicCodeDiscount) {
        codeDiscountNode {
          id
          codeDiscount {
            ... on DiscountCodeBasic {
              title codes(first: 1) { edges { node { code } } }
            }
          }
        }
        userErrors { field code message }
      }
    }
  `;

  const response = await admin.graphql(mutation, {
    variables: {
      basicCodeDiscount: {
        title: config.title,
        code,
        startsAt: new Date().toISOString(),
        ...(config.expiresAt && { endsAt: config.expiresAt.toISOString() }),
        customerGets: {
          value: { percentage: config.value / 100 }, // Shopify uses 0-1 scale
          items: { all: true },
        },
        appliesOncePerCustomer: true,
        usageLimit: config.usageLimit ?? 1,
        ...(config.minimumAmount && {
          minimumRequirement: {
            subtotal: { greaterThanOrEqualToSubtotal: String(config.minimumAmount) },
          },
        }),
      },
    },
  });

  const { data } = await response.json();
  if (data.discountCodeBasicCreate.userErrors?.length > 0) {
    throw new Error(data.discountCodeBasicCreate.userErrors[0].message);
  }

  return code;
}

async function createFixedDiscount(admin: any, code: string, config: DiscountConfig): Promise<string | null> {
  const mutation = `#graphql
    mutation discountCodeBasicCreate($basicCodeDiscount: DiscountCodeBasicInput!) {
      discountCodeBasicCreate(basicCodeDiscount: $basicCodeDiscount) {
        codeDiscountNode { id }
        userErrors { field message }
      }
    }
  `;

  const response = await admin.graphql(mutation, {
    variables: {
      basicCodeDiscount: {
        title: config.title,
        code,
        startsAt: new Date().toISOString(),
        ...(config.expiresAt && { endsAt: config.expiresAt.toISOString() }),
        customerGets: {
          value: { discountAmount: { amount: String(config.value), appliesOnEachItem: false } },
          items: { all: true },
        },
        appliesOncePerCustomer: true,
        usageLimit: config.usageLimit ?? 1,
      },
    },
  });

  const { data } = await response.json();
  if (data.discountCodeBasicCreate.userErrors?.length > 0) {
    throw new Error(data.discountCodeBasicCreate.userErrors[0].message);
  }

  return code;
}

async function createFreeShippingDiscount(admin: any, code: string, config: DiscountConfig): Promise<string | null> {
  const mutation = `#graphql
    mutation discountCodeFreeShippingCreate($freeShippingCodeDiscount: DiscountCodeFreeShippingInput!) {
      discountCodeFreeShippingCreate(freeShippingCodeDiscount: $freeShippingCodeDiscount) {
        codeDiscountNode { id }
        userErrors { field message }
      }
    }
  `;

  const response = await admin.graphql(mutation, {
    variables: {
      freeShippingCodeDiscount: {
        title: config.title,
        code,
        startsAt: new Date().toISOString(),
        appliesOncePerCustomer: true,
        usageLimit: config.usageLimit ?? 1,
      },
    },
  });

  const { data } = await response.json();
  if (data.discountCodeFreeShippingCreate.userErrors?.length > 0) {
    throw new Error(data.discountCodeFreeShippingCreate.userErrors[0].message);
  }

  return code;
}
```

