## DISCOUNT REVEAL COMPONENT (Storefront Widget)

```javascript
// extensions/quiz-widget/assets/discount.js

function renderDiscountReveal(container, discountCode, primaryColor) {
  if (!discountCode) return;

  const el = document.createElement("div");
  el.className = "qs-discount-reveal";
  el.innerHTML = `
    <div class="qs-discount-box">
      <p class="qs-discount-label">Your exclusive discount code:</p>
      <div class="qs-discount-code-row">
        <code class="qs-discount-code">${escapeHtml(discountCode)}</code>
        <button class="qs-discount-copy" style="background:${primaryColor}" data-code="${escapeAttr(discountCode)}">
          Copy
        </button>
      </div>
      <p class="qs-discount-hint">Applied automatically at checkout or enter code manually.</p>
    </div>
  `;

  el.querySelector(".qs-discount-copy").addEventListener("click", async (e) => {
    const code = e.target.getAttribute("data-code");
    try {
      await navigator.clipboard.writeText(code);
      e.target.textContent = "Copied!";
      setTimeout(() => { e.target.textContent = "Copy"; }, 2000);
    } catch {
      e.target.textContent = "Copy code above";
    }
  });

  container.appendChild(el);
}

// Auto-apply discount via checkout URL
function buildCheckoutUrlWithDiscount(discountCode) {
  return `/checkout?discount=${encodeURIComponent(discountCode)}`;
}
