// tests/services/scoring.test.ts
import { describe, it, expect, beforeEach, vi } from "vitest";
import db from "../../app/db.server";
import { scoreQuizResponse } from "../../app/services/scoring.server";

const mockQuestions = [
  {
    id: "q1",
    quizId: "quiz1",
    type: "single-choice",
    settings: "{}",
    answers: [
      { id: "a1", score: 10, productTags: JSON.stringify(["dry-skin", "hydrating"]), metadata: "{}" },
      { id: "a2", score: 5, productTags: JSON.stringify(["oily-skin"]), metadata: "{}" },
    ],
  },
  {
    id: "q2",
    quizId: "quiz1",
    type: "single-choice",
    settings: JSON.stringify({ weight: 2 }),
    answers: [
      { id: "a3", score: 10, productTags: JSON.stringify(["anti-aging"]), metadata: JSON.stringify({ personalityType: "mature" }) },
      { id: "a4", score: 5, productTags: JSON.stringify(["brightening"]), metadata: "{}" },
    ],
  },
];

describe("scoreQuizResponse", () => {
  beforeEach(() => {
    vi.mocked(db.question.findMany).mockResolvedValue(mockQuestions as any);
  });

  it("accumulates scores correctly", async () => {
    const result = await scoreQuizResponse("quiz1", [
      { questionId: "q1", answerId: "a1", value: "dry-skin" },
      { questionId: "q2", answerId: "a3", value: "anti-aging" },
    ]);
    // q1: score 10 (weight 1) = 10; q2: score 10 (weight 2) = 20
    expect(result.totalScore).toBe(30);
  });

  it("collects tags from answers", async () => {
    const result = await scoreQuizResponse("quiz1", [
      { questionId: "q1", answerId: "a1", value: "dry-skin" },
    ]);
    expect(result.tags).toContain("dry-skin");
    expect(result.tags).toContain("hydrating");
  });

  it("deduplicates tags (case-insensitive)", async () => {
    vi.mocked(db.question.findMany).mockResolvedValue([{
      ...mockQuestions[0],
      answers: [
        { id: "a1", score: 5, productTags: JSON.stringify(["Dry-Skin", "dry-skin", "HYDRATING"]), metadata: "{}" },
      ],
    }] as any);

    const result = await scoreQuizResponse("quiz1", [
      { questionId: "q1", answerId: "a1", value: "test" },
    ]);
    const uniqueTags = new Set(result.tags);
    expect(uniqueTags.size).toBe(result.tags.length); // No duplicates
    expect(result.tags.every(t => t === t.toLowerCase())).toBe(true); // All lowercase
  });

  it("determines personality type by highest vote", async () => {
    const result = await scoreQuizResponse("quiz1", [
      { questionId: "q2", answerId: "a3", value: "anti-aging" },
    ]);
    expect(result.personalityType).toBe("mature");
  });

  it("never returns negative totalScore", async () => {
    vi.mocked(db.question.findMany).mockResolvedValue([{
      ...mockQuestions[0],
      answers: [{ id: "a1", score: -50, productTags: "[]", metadata: "{}" }],
    }] as any);

    const result = await scoreQuizResponse("quiz1", [
      { questionId: "q1", answerId: "a1", value: "test" },
    ]);
    expect(result.totalScore).toBeGreaterThanOrEqual(0);
  });

  it("handles unknown questionId gracefully", async () => {
    const result = await scoreQuizResponse("quiz1", [
      { questionId: "unknown-q", answerId: "unknown-a", value: "test" },
    ]);
    expect(result.totalScore).toBe(0);
    expect(result.tags).toHaveLength(0);
  });
});
```

