const mockProducts = [
  { productGid: "gid://shopify/Product/1", title: "Moisturizer", imageUrl: null, handle: "moisturizer",
    tags: JSON.stringify(["dry-skin", "hydrating", "gentle"]), score: 50, collections: "[]", priceMin: 25, priceMax: 25 },
  { productGid: "gid://shopify/Product/2", title: "Cleanser", imageUrl: null, handle: "cleanser",
    tags: JSON.stringify(["oily-skin", "clarifying"]), score: 30, collections: "[]", priceMin: 15, priceMax: 15 },
  { productGid: "gid://shopify/Product/3", title: "Serum", imageUrl: null, handle: "serum",
    tags: JSON.stringify(["anti-aging", "hydrating"]), score: 80, collections: "[]", priceMin: 45, priceMax: 45 },
];

describe("scoreProducts", () => {
  it("tag-match mode scores by tag overlap", () => {
    const results = scoreProducts(["dry-skin", "hydrating"], mockProducts, "tag-match");
    expect(results[0].productGid).toBe("gid://shopify/Product/1"); // 2 tag matches
    expect(results.every(p => p.totalScore > 0)).toBe(true);
  });

  it("point-based mode scores by product base score", () => {
    const results = scoreProducts([], mockProducts, "point-based");
    expect(results[0].productGid).toBe("gid://shopify/Product/3"); // score: 80
  });

  it("hybrid mode combines tag + base score", () => {
    const results = scoreProducts(["hydrating"], mockProducts, "hybrid");
    // Moisturizer: 1 tag match (10) + 50 = 60; Serum: 1 tag match (10) + 80 = 90
    expect(results[0].productGid).toBe("gid://shopify/Product/3");
  });

  it("tag comparison is case-insensitive", () => {
    const results = scoreProducts(["DRY-SKIN"], mockProducts, "tag-match");
    const moisturizer = results.find(p => p.productGid === "gid://shopify/Product/1");
    expect(moisturizer).toBeDefined();
    expect(moisturizer!.totalScore).toBeGreaterThan(0);
  });

  it("filters out products with zero score", () => {
    const results = scoreProducts(["nonexistent-tag"], mockProducts, "tag-match");
    expect(results).toHaveLength(0);
  });

  it("returns sorted by totalScore descending", () => {
    const results = scoreProducts(["hydrating", "anti-aging"], mockProducts, "tag-match");
    for (let i = 0; i < results.length - 1; i++) {
      expect(results[i].totalScore).toBeGreaterThanOrEqual(results[i + 1].totalScore);
    }
  });
});
