import { describe, it, expect, beforeEach, vi } from "vitest";
import db from "../../app/db.server";
import { checkUsageLimit, requirePlan } from "../../app/services/billing.server";

describe("checkUsageLimit", () => {
  it("allows unlimited responses on enterprise plan", async () => {
    vi.mocked(db.subscription.findUnique).mockResolvedValue({ plan: "enterprise", monthlyResponses: 99999, responseResetAt: new Date(Date.now() + 9999999) } as any);
    const result = await checkUsageLimit("shop.myshopify.com", "responses");
    expect(result.allowed).toBe(true);
  });

  it("blocks responses when free plan limit reached", async () => {
    vi.mocked(db.subscription.findUnique).mockResolvedValue({ plan: "free", monthlyResponses: 100, responseResetAt: new Date(Date.now() + 9999999) } as any);
    const result = await checkUsageLimit("shop.myshopify.com", "responses");
    expect(result.allowed).toBe(false);
    expect(result.current).toBe(100);
    expect(result.limit).toBe(100);
  });

  it("returns plan name in result", async () => {
    vi.mocked(db.subscription.findUnique).mockResolvedValue({ plan: "starter", monthlyResponses: 0, responseResetAt: new Date(Date.now() + 9999999) } as any);
    const result = await checkUsageLimit("shop.myshopify.com", "responses");
    expect(result.plan).toBe("starter");
  });
});

describe("requirePlan", () => {
  it("throws 402 when plan is insufficient", async () => {
    vi.mocked(db.subscription.findUnique).mockResolvedValue({ plan: "free", status: "active" } as any);
    await expect(requirePlan("shop.myshopify.com", "pro"))
      .rejects.toMatchObject({ status: 402 });
  });

  it("passes when plan is sufficient", async () => {
    vi.mocked(db.subscription.findUnique).mockResolvedValue({ plan: "pro", status: "active" } as any);
    await expect(requirePlan("shop.myshopify.com", "pro")).resolves.toBeUndefined();
  });
});
```

