import { useLoaderData } from "react-router";
import { authenticate } from "../shopify.server";
import { getOnboardingState } from "../services/onboarding.server";
import { Page, Layout, Card, BlockStack, InlineStack, Text, Button, Badge, Icon, ProgressBar } from "@shopify/polaris";
import { CheckCircleIcon, CircleIcon } from "@shopify/polaris-icons";

export async function loader({ request }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const state = await getOnboardingState(session.shop);
  return json({ state });
}

const STEPS = [
  { key: "hasInstalledApp", title: "Install QuizSnap", description: "App successfully installed", action: null },
  { key: "hasCreatedQuiz", title: "Create your first quiz", description: "Build a product recommendation quiz", action: { label: "Create Quiz", url: "/app/quizzes/new" } },
  { key: "hasAddedQuestions", title: "Add at least 3 questions", description: "Guide shoppers to the right products", action: { label: "Edit Quiz", url: "/app/quizzes" } },
  { key: "hasConnectedProducts", title: "Sync your products", description: "Connect your catalog for recommendations", action: { label: "Sync Products", url: "/app/products" } },
  { key: "hasPublishedQuiz", title: "Publish your quiz", description: "Make it live for shoppers", action: { label: "View Quizzes", url: "/app/quizzes" } },
  { key: "hasInstalledWidget", title: "Install the quiz widget", description: "Add the quiz to your storefront", action: { label: "Get Embed Code", url: "/app/quizzes" } },
];

export default function OnboardingPage() {
  const { state } = useLoaderData<typeof loader>();

  if (state.completionPercent === 100) {
    return (
      <Page title="Setup Complete 🎉">
        <Card>
          <BlockStack gap="400" align="center">
            <Text as="h2" variant="headingMd">You're all set!</Text>
            <Text as="p" tone="subdued">Your quiz is live and ready to help shoppers find perfect products.</Text>
            <Button url="/app" variant="primary">Go to Dashboard</Button>
