// app/services/onboarding.server.ts
export interface OnboardingState {
  hasInstalledApp: boolean;
  hasCreatedQuiz: boolean;
  hasAddedQuestions: boolean;
  hasConnectedProducts: boolean;
  hasPublishedQuiz: boolean;
  hasInstalledWidget: boolean;
  completionPercent: number;
}

export async function getOnboardingState(shop: string): Promise<OnboardingState> {
  const [quizCount, activeQuizCount, productCount, questionCount] = await Promise.all([
    db.quiz.count({ where: { shop } }),
    db.quiz.count({ where: { shop, status: "active" } }),
    db.productMapping.count({ where: { shop, status: "active" } }),
    db.question.count({ where: { quiz: { shop } } }),
  ]);

  const state: OnboardingState = {
    hasInstalledApp: true, // They're here
    hasCreatedQuiz: quizCount > 0,
    hasAddedQuestions: questionCount >= 3, // Need at least 3 questions
    hasConnectedProducts: productCount > 0,
    hasPublishedQuiz: activeQuizCount > 0,
    hasInstalledWidget: activeQuizCount > 0 && productCount > 0,
    completionPercent: 0,
  };

  const completedSteps = Object.values(state).filter(Boolean).length - 1; // Exclude completionPercent
  state.completionPercent = Math.round((completedSteps / 5) * 100);

  return state;
}
