import { nanoid } from "nanoid"; // npm install nanoid

export async function createShareableResponse(
  responseData: Parameters<typeof db.quizResponse.create>[0]["data"]
): Promise<{ response: any; shareId: string }> {
  const shareId = nanoid(10); // Short, URL-safe ID
  const response = await db.quizResponse.create({
    data: { ...responseData, shareId },
  });
