// app/routes/share.$shareId.tsx
import { json, type LoaderFunctionArgs } from "react-router";
import db from "../db.server";

export async function loader({ params }: LoaderFunctionArgs) {
  const response = await db.quizResponse.findFirst({
    where: { shareId: params.shareId },
    include: {
      quiz: { select: { title: true, description: true, shop: true } },
      resultPage: { select: { title: true, description: true } },
    },
  });

  if (!response) throw new Response("Not Found", { status: 404 });

  return json({
    shareId: params.shareId,
    quizTitle: response.quiz.title,
    resultTitle: response.resultPage?.title ?? "My Results",
    description: response.resultPage?.description ?? `I took the ${response.quiz.title} quiz!`,
    shop: response.quiz.shop,
    shareUrl: `${process.env.SHOPIFY_APP_URL}/share/${params.shareId}`,
  });
}

// Open Graph meta tags for social preview
export function meta({ data }: { data: any }) {
  if (!data) return [];
  return [
    { title: `My ${data.quizTitle} Results` },
    { name: "description", content: data.description },
    { property: "og:title", content: `${data.resultTitle} — ${data.quizTitle}` },
    { property: "og:description", content: data.description },
    { property: "og:type", content: "website" },
    { property: "og:url", content: data.shareUrl },
    { name: "twitter:card", content: "summary" },
    { name: "twitter:title", content: `${data.resultTitle} — ${data.quizTitle}` },
  ];
}
```

