```javascript
// extensions/quiz-widget/assets/sharing.js

function renderShareButtons(container, shareUrl, quizTitle, sessionId) {
  const encodedUrl = encodeURIComponent(shareUrl);
  const encodedText = encodeURIComponent(`I just found my perfect products with the ${quizTitle} quiz! Check yours:`);

  const el = document.createElement("div");
  el.className = "qs-share-section";
  el.innerHTML = `
    <p class="qs-share-label">Share your results:</p>
    <div class="qs-share-buttons">
      <a href="https://twitter.com/intent/tweet?url=${encodedUrl}&text=${encodedText}"
         class="qs-share-btn qs-share-twitter" target="_blank" rel="noopener">Twitter</a>
      <a href="https://www.facebook.com/sharer/sharer.php?u=${encodedUrl}"
         class="qs-share-btn qs-share-facebook" target="_blank" rel="noopener">Facebook</a>
      <a href="https://wa.me/?text=${encodedText}%20${encodedUrl}"
         class="qs-share-btn qs-share-whatsapp" target="_blank" rel="noopener">WhatsApp</a>
      <button class="qs-share-btn qs-share-copy" data-url="${escapeAttr(shareUrl)}">Copy Link</button>
    </div>
  `;

  el.querySelector(".qs-share-copy").addEventListener("click", async (e) => {
    const url = e.target.getAttribute("data-url");
    try {
      await navigator.clipboard.writeText(url);
      e.target.textContent = "Copied!";
      setTimeout(() => { e.target.textContent = "Copy Link"; }, 2000);
    } catch {
      e.target.textContent = url; // Fallback: show the URL
    }
  });

  // Track share button clicks
  el.querySelectorAll(".qs-share-btn").forEach(btn => {
    btn.addEventListener("click", (e) => {
      const platform = Array.from(e.target.classList)
        .find(c => c.startsWith("qs-share-") && c !== "qs-share-btn")
        ?.replace("qs-share-", "") ?? "unknown";
      trackEvent("share_clicked", sessionId, { platform, quizTitle });
    });
  });

  container.appendChild(el);
}
```

---

## SELF-VALIDATION CHECKLIST

- [ ] `shareId` is URL-safe and collision-resistant (nanoid(10))
- [ ] Share page is fully public — no auth required
- [ ] Open Graph tags populated dynamically from result data
- [ ] Share buttons open in new tab (`target="_blank" rel="noopener"`)
- [ ] `share_clicked` analytics event tracks platform
- [ ] Share URL points to public page (not admin)

---

## NEVER

- Never include merchant's shop data in public share URLs
- Never require auth to view a shared result
- Never generate share URLs without a valid shareId from DB

