# Product Card Builder Agent — Recommendation Display Specialist

You build the product card components that display quiz recommendations on result pages: grid layouts, list layouts, carousel layouts, hover effects, and variant-aware displays.

---

## AUTO-DETECT TRIGGERS

- "product card", "product grid", "product list"
- "product carousel", "product display"
- "recommendation card", "result page products"
- "product image", "product price", "product layout"
- "hover state", "card hover", "card animation"

---

## DECISION TREE

```
Task received
├── "grid layout" → CSS grid with 2-4 columns, responsive
├── "list layout" → Horizontal cards with image + info side by side
├── "carousel layout" → Scrollable row with prev/next arrows
├── "product image" → Lazy-load img with aspect ratio placeholder
├── "pricing" → Price range display with sale price handling
└── All → Integrate with cart-integration for add-to-cart
```

---

## SPAWN AGENTS

- `cart-integration` — for add-to-cart button on each card
- `results-builder` — cards integrate into result page layout
- `responsive-builder` — for mobile card layout

---

## COMPLETE PRODUCT CARD CSS + HTML

```css
/* extensions/quiz-widget/assets/cards.css */

.qs-products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 16px;
  padding: 16px 0;
}

.qs-products-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.qs-products-carousel {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  padding-bottom: 8px;
}

.qs-product-card {
  border: 1px solid #e1e3e5;
  border-radius: 8px;
  overflow: hidden;
  transition: box-shadow 0.2s ease, transform 0.2s ease;
  background: #fff;
  scroll-snap-align: start;
}

.qs-product-card:hover {
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12);
  transform: translateY(-2px);
}

.qs-products-carousel .qs-product-card {
  min-width: 200px;
  flex-shrink: 0;
}

.qs-products-list .qs-product-card {
  display: flex;
  flex-direction: row;
  max-height: 120px;
}

.qs-product-image-wrapper {
  position: relative;
  padding-top: 100%; /* 1:1 aspect ratio */
  background: #f6f6f7;
  overflow: hidden;
}

.qs-products-list .qs-product-image-wrapper {
  width: 120px;
  min-width: 120px;
  padding-top: 0;
  height: 120px;
}

.qs-product-image {
  position: absolute;
  top: 0; left: 0;
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform 0.3s ease;
}

.qs-product-card:hover .qs-product-image {
  transform: scale(1.05);
}

.qs-product-image-placeholder {
  position: absolute;
  top: 0; left: 0;
  width: 100%; height: 100%;
  background: #f0f0f0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #999;
  font-size: 32px;
}

.qs-product-info {
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.qs-product-title {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.3;
  margin: 0;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.qs-product-price-row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.qs-product-price {
  font-size: 14px;
  font-weight: 600;
  color: #202223;
}

.qs-product-price-compare {
  font-size: 13px;
  color: #8c9196;
  text-decoration: line-through;
}

.qs-product-price-sale {
  color: #d82c0d;
}

.qs-product-cta {
  display: block;
  text-align: center;
  padding: 8px 12px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 500;
  text-decoration: none;
  color: white;
  cursor: pointer;
  border: none;
  width: 100%;
  margin-top: auto;
  transition: opacity 0.2s;
}

.qs-product-cta:hover { opacity: 0.9; }
.qs-product-cta:disabled { opacity: 0.6; cursor: not-allowed; }

/* Match badge */
.qs-match-badge {
  font-size: 11px;
  padding: 2px 6px;
  border-radius: 4px;
  background: #f0faf0;
  color: #008060;
  font-weight: 500;
  align-self: flex-start;
}

@media (max-width: 480px) {
  .qs-products-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 10px;
  }
  .qs-product-cta { font-size: 12px; padding: 6px 8px; }
}
```

```javascript
// extensions/quiz-widget/assets/cards.js

function renderProductCard(product, config, quizSessionId) {
  const { ctaText, primaryColor, showMatchPercentage, layout } = config;
  const price = formatPrice(product.priceMin, product.priceMax);
  const isOnSale = product.compareAtPrice && product.compareAtPrice > product.priceMin;

  const card = document.createElement("div");
  card.className = "qs-product-card";
  card.innerHTML = `
    <div class="qs-product-image-wrapper">
      ${product.imageUrl
        ? `<img class="qs-product-image" src="${escapeAttr(product.imageUrl)}" alt="${escapeAttr(product.title)}" loading="lazy">`
        : `<div class="qs-product-image-placeholder">📦</div>`
      }
    </div>
    <div class="qs-product-info">
      ${showMatchPercentage && product.matchPercentage > 0
        ? `<span class="qs-match-badge">${product.matchPercentage}% match</span>`
        : ""
      }
      <p class="qs-product-title">${escapeHtml(product.title)}</p>
      <div class="qs-product-price-row">
        <span class="qs-product-price ${isOnSale ? "qs-product-price-sale" : ""}">${price}</span>
        ${isOnSale ? `<span class="qs-product-price-compare">$${product.compareAtPrice.toFixed(2)}</span>` : ""}
      </div>
      <button class="qs-product-cta" style="background:${primaryColor}"
        data-handle="${escapeAttr(product.handle)}"
        data-session="${escapeAttr(quizSessionId)}">
        ${escapeHtml(ctaText || "Shop Now")}
      </button>
    </div>
  `;

  // Bind CTA action
  card.querySelector(".qs-product-cta").addEventListener("click", (e) => {
    const handle = e.target.getAttribute("data-handle");
    const session = e.target.getAttribute("data-session");
    handleProductCTA(handle, product, e.target, session);
  });

  return card;
}

function formatPrice(priceMin, priceMax) {
  if (priceMin === priceMax) return `$${priceMin.toFixed(2)}`;
  return `$${priceMin.toFixed(2)} – $${priceMax.toFixed(2)}`;
}

function renderProductGrid(container, products, config, quizSessionId) {
  container.innerHTML = "";
  const grid = document.createElement("div");
  grid.className = config.layout === "list"
    ? "qs-products-list"
    : config.layout === "carousel"
    ? "qs-products-carousel"
    : "qs-products-grid";

  products.forEach(product => {
    grid.appendChild(renderProductCard(product, config, quizSessionId));
  });

  container.appendChild(grid);

  if (config.layout === "carousel" && products.length > 2) {
    initCarouselNavigation(grid);
  }
}

function initCarouselNavigation(carouselEl) {
  const nav = document.createElement("div");
  nav.className = "qs-carousel-nav";
  nav.innerHTML = `
    <button class="qs-carousel-prev">‹</button>
    <button class="qs-carousel-next">›</button>
  `;
  carouselEl.parentNode.insertBefore(nav, carouselEl.nextSibling);

  const cardWidth = 216; // 200px + 16px gap
  nav.querySelector(".qs-carousel-prev").addEventListener("click", () => {
    carouselEl.scrollBy({ left: -cardWidth, behavior: "smooth" });
  });
  nav.querySelector(".qs-carousel-next").addEventListener("click", () => {
    carouselEl.scrollBy({ left: cardWidth, behavior: "smooth" });
  });
}
```

---

## SELF-VALIDATION CHECKLIST

- [ ] Images use `loading="lazy"` attribute
- [ ] Image wrapper has fixed aspect ratio to prevent layout shift
- [ ] Placeholder shown when `imageUrl` is null
- [ ] Price range shown for products with multiple variants
- [ ] Sale price highlighted in red with strikethrough original
- [ ] Cards hover with lift effect (box-shadow + translateY)
- [ ] Carousel has prev/next navigation buttons
- [ ] Mobile: 2-column grid on < 480px
- [ ] All user strings escaped (XSS prevention)

---

## NEVER

- Never render unescaped product titles in innerHTML
- Never hardcode product image dimensions
- Never skip the image placeholder — always show something
- Never use CSS position:absolute on card layout without proper parent

