name: rate-limiter
description: "Use when implementing API rate limiting, protecting public endpoints from abuse, throttling, or handling Shopify API rate limits. Triggered by: rate limit, throttle, API abuse, too many requests, 429, quota, public endpoint protection, DDoS"
model: sonnet
---

# Rate Limiter — Public Endpoint Protection

## AUTO-DETECT TRIGGERS
- User mentions: rate limit, 429, throttle, API abuse, protect endpoint
- Public quiz embed endpoint receiving high traffic
- Shopify API returning THROTTLED errors
- Adding protection to `/api/quiz/*` public routes

## DECISION TREE
```
Need rate limiting? →
  Public storefront endpoint? → Per-IP sliding window (50 req/min)
  Per-shop admin API? → Per-shop limit (100 req/min)
  Shopify Admin API? → Cost-based throttle with backoff
  Hit 429? → Return Retry-After header with wait time
  Trusted source? → Bypass header (HMAC-signed internal calls)
```

## IN-MEMORY SLIDING WINDOW RATE LIMITER

```typescript
// app/utils/rate-limiter.server.ts

interface RateLimitEntry {
  requests: number[];   // Timestamps of requests in the current window
  blocked: boolean;
}

// Simple in-memory store — works for single-process deployments
// For multi-instance: swap Map for Redis (Upstash recommended for Shopify)
const store = new Map<string, RateLimitEntry>();

// Cleanup expired entries every 5 minutes
setInterval(() => {
  const now = Date.now();
  for (const [key, entry] of store.entries()) {
    // Remove if all requests are outside the max window (1 hour)
    if (entry.requests.every(t => now - t > 3_600_000)) {
      store.delete(key);
    }
  }
}, 5 * 60 * 1000);

export interface RateLimitConfig {
  windowMs: number;     // Window size in ms (e.g., 60_000 = 1 minute)
  maxRequests: number;  // Max requests per window
  keyPrefix?: string;
}

export interface RateLimitResult {
  allowed: boolean;
  remaining: number;
  resetAt: number;      // Unix timestamp when window resets
  retryAfter?: number;  // Seconds to wait if blocked
}

export function checkRateLimit(
  identifier: string,
  config: RateLimitConfig
): RateLimitResult {
  const key = `${config.keyPrefix ?? "rl"}:${identifier}`;
  const now = Date.now();
  const windowStart = now - config.windowMs;

  const entry = store.get(key) ?? { requests: [], blocked: false };

  // Remove requests outside the sliding window
  entry.requests = entry.requests.filter(t => t > windowStart);

  if (entry.requests.length >= config.maxRequests) {
    const oldestInWindow = entry.requests[0];
    const resetAt = oldestInWindow + config.windowMs;
    const retryAfter = Math.ceil((resetAt - now) / 1000);

    store.set(key, entry);
    return { allowed: false, remaining: 0, resetAt, retryAfter };
  }

  entry.requests.push(now);
  store.set(key, entry);

  const resetAt = (entry.requests[0] ?? now) + config.windowMs;
  const remaining = config.maxRequests - entry.requests.length;

  return { allowed: true, remaining, resetAt };
}
```

## RATE LIMIT CONFIGS FOR QUIZSNAP

```typescript
// app/config/rate-limits.ts
export const RATE_LIMITS = {
  // Public storefront quiz API — by IP
  QUIZ_EMBED: { windowMs: 60_000, maxRequests: 60, keyPrefix: "quiz" },
  // Quiz submission — by IP (prevent spam submissions)
  QUIZ_SUBMIT: { windowMs: 60_000, maxRequests: 10, keyPrefix: "submit" },
  // Public analytics endpoint (if any) — by shop
  ANALYTICS_PUBLIC: { windowMs: 60_000, maxRequests: 30, keyPrefix: "analytics" },
  // Admin API calls — per shop
  ADMIN_API: { windowMs: 60_000, maxRequests: 100, keyPrefix: "admin" },
} as const;
```

## MIDDLEWARE WRAPPER FOR PUBLIC ROUTES

```typescript
// app/utils/with-rate-limit.server.ts
import { checkRateLimit, type RateLimitConfig } from "./rate-limiter.server";

export function withRateLimit(
  request: Request,
  identifier: string,
  config: RateLimitConfig
): Response | null {
  const result = checkRateLimit(identifier, config);

  if (!result.allowed) {
    return new Response(
      JSON.stringify({
        error: "Too many requests",
        retryAfter: result.retryAfter,
        message: `Rate limit exceeded. Try again in ${result.retryAfter} seconds.`,
      }),
      {
        status: 429,
        headers: {
          "Content-Type": "application/json",
          "X-RateLimit-Limit": String(config.maxRequests),
          "X-RateLimit-Remaining": "0",
          "X-RateLimit-Reset": String(result.resetAt),
          "Retry-After": String(result.retryAfter),
        },
      }
    );
  }

  return null; // No rate limit block — proceed
}
```

## USAGE IN PUBLIC QUIZ ROUTES

```typescript
// app/routes/api.quiz.$quizId.tsx — public endpoint
import { RATE_LIMITS } from "~/config/rate-limits";
import { withRateLimit } from "~/utils/with-rate-limit.server";

export async function loader({ request, params }: LoaderFunctionArgs) {
  // Get client IP (Shopify deployments often use Cloudflare)
  const ip = request.headers.get("cf-connecting-ip")
    ?? request.headers.get("x-forwarded-for")?.split(",")[0]?.trim()
    ?? "unknown";

  // Check rate limit before any DB or API calls
  const rateLimitResponse = withRateLimit(request, ip, RATE_LIMITS.QUIZ_EMBED);
  if (rateLimitResponse) return rateLimitResponse;

  const { quizId } = params;
  // ... load quiz data
}

export async function action({ request, params }: ActionFunctionArgs) {
  const ip = request.headers.get("cf-connecting-ip")
    ?? request.headers.get("x-forwarded-for")?.split(",")[0]?.trim()
    ?? "unknown";

  const rateLimitResponse = withRateLimit(request, ip, RATE_LIMITS.QUIZ_SUBMIT);
  if (rateLimitResponse) return rateLimitResponse;

  // ... handle quiz submission
}
```

## SHOPIFY API RATE LIMIT HANDLER

```typescript
// app/utils/shopify-throttle.server.ts
export async function withShopifyThrottle<T>(
  fn: () => Promise<T>,
  maxRetries = 3
): Promise<T> {
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      return await fn();
    } catch (err: any) {
      const isThrottled =
        err?.message?.includes("THROTTLED") ||
        err?.extensions?.code === "THROTTLED";

      if (!isThrottled || attempt === maxRetries - 1) throw err;

      const backoffMs = Math.pow(2, attempt) * 1000 + Math.random() * 500;
      console.warn(`Shopify API throttled, retrying in ${Math.round(backoffMs)}ms (attempt ${attempt + 1})`);
      await new Promise(r => setTimeout(r, backoffMs));
    }
  }
  throw new Error("Max retries exceeded");
}
```

## TRUSTED SOURCE BYPASS (Internal Services)

```typescript
// app/utils/rate-limit-bypass.server.ts
import crypto from "crypto";

const INTERNAL_SECRET = process.env.INTERNAL_API_SECRET ?? "";

export function generateBypassToken(payload: string): string {
  return crypto.createHmac("sha256", INTERNAL_SECRET).update(payload).digest("hex");
}

export function isTrustedSource(request: Request): boolean {
  const token = request.headers.get("x-internal-token");
  const timestamp = request.headers.get("x-internal-timestamp");
  if (!token || !timestamp) return false;

  // Reject stale tokens (>5 minutes)
  if (Date.now() - Number(timestamp) > 5 * 60 * 1000) return false;

  const expected = generateBypassToken(timestamp);
  return crypto.timingSafeEqual(Buffer.from(token), Buffer.from(expected));
}
```

## SPAWN AGENTS
- `graphql-specialist` — Shopify GraphQL rate limit handling
- `api-builder` — all public API routes need rate limiting
- `storefront-builder` — quiz embed endpoints are public and need protection

## SELF-VALIDATION CHECKLIST
- [ ] `Retry-After` header included in all 429 responses (RFC 6585)
- [ ] `X-RateLimit-*` headers included for API transparency
- [ ] IP extracted from `cf-connecting-ip` first (Cloudflare), then `x-forwarded-for`
- [ ] Sliding window (not fixed window) to prevent bursting at window boundaries
- [ ] In-memory store cleaned up periodically (prevents memory leak)
- [ ] Rate limit check happens BEFORE any DB or API calls
- [ ] Shopify API retry uses exponential backoff + jitter
- [ ] Trusted bypass uses HMAC + timestamp (not static token)
- [ ] Bypass token has 5-minute expiry (prevents replay attacks)
- [ ] Different limits for read (60 req/min) vs write (10 req/min) endpoints

## NEVER
- Never use a fixed window rate limiter (allows 2x burst at boundaries)
- Never return 429 without a `Retry-After` header
- Never rate limit by session cookie alone (easy to bypass)
- Never skip rate limiting on quiz submission endpoints
- Never use in-memory rate limiter in multi-instance deployments without Redis

