```typescript
// app/services/flow.server.ts
interface FlowTriggerPayload {
  quiz_id: string;
  quiz_title: string;
  customer_email?: string;
  result_tags?: string;
  total_score?: number;
  personality_type?: string;
  session_id: string;
}

export async function triggerFlowEvent(
  admin: any,
  shop: string,
  triggerKey: "quiz_completed" | "quiz_started" | "quiz_abandoned",
  payload: FlowTriggerPayload
): Promise<void> {
  try {
    const mutation = `#graphql
      mutation flowTriggerReceive($handle: String!, $payload: String!) {
        flowTriggerReceive(handle: $handle, payload: $payload) {
          userErrors { field message }
        }
      }
    `;

    const response = await admin.graphql(mutation, {
      variables: {
        handle: triggerKey,
        payload: JSON.stringify(payload),
      },
    });

    const { data } = await response.json();
    if (data.flowTriggerReceive?.userErrors?.length > 0) {
      console.error("Flow trigger error:", data.flowTriggerReceive.userErrors[0].message);
    }
  } catch (e) {
    // Never crash quiz operations due to Flow issues
    console.error("Flow trigger failed (non-fatal):", e);
  }
}

// Called after quiz completion in api.quiz.$slug.submit.tsx
export async function triggerQuizCompletedFlow(
  admin: any,
  shop: string,
  completionData: {
    quizId: string;
    quizTitle: string;
    email?: string;
    tags: string[];
    score: number;
    personalityType?: string;
    sessionId: string;
  }
): Promise<void> {
  await triggerFlowEvent(admin, shop, "quiz_completed", {
    quiz_id: completionData.quizId,
    quiz_title: completionData.quizTitle,
    customer_email: completionData.email,
    result_tags: completionData.tags.join(", "),
    total_score: completionData.score,
    personality_type: completionData.personalityType,
    session_id: completionData.sessionId,
  });
}
```

---

## INTEGRATION WITH QUIZ SUBMIT

```typescript
// In api.quiz.$slug.submit.tsx — after processing response:
// Fire Flow trigger (non-blocking)
triggerQuizCompletedFlow(admin, shop, {
  quizId: quiz.id,
  quizTitle: quiz.title,
  email: submittedEmail,
  tags: scored.tags,
  score: scored.totalScore,
  personalityType: scored.personalityType ?? undefined,
  sessionId,
}).catch(e => console.error("Flow trigger failed:", e)); // Fire and forget
```

---

## EXAMPLE FLOW WORKFLOWS MERCHANTS CAN BUILD

```
1. Quiz Completed → Has "dry-skin" tag → Send "Dry Skin Care Guide" email
2. Quiz Completed → Score > 80 → Apply "loyalty" tag to customer
3. Quiz Completed → Personality = "minimalist" → Add to Klaviyo segment
4. Quiz Started → No completion after 24h → Send quiz reminder email
5. Quiz Completed → Customer email provided → Create draft order with quiz products
```

---

## SELF-VALIDATION CHECKLIST

- [ ] Flow triggers registered in shopify.app.toml
- [ ] `triggerFlowEvent()` wrapped in try/catch — never crashes quiz submit
- [ ] Flow trigger fires AFTER response is stored (not before)
- [ ] Customer email only included if actually captured in quiz
- [ ] `shopify app deploy` run to register Flow triggers with Shopify

---

## NEVER

- Never block quiz response on Flow trigger success
- Never include admin-only data (full response details) in Flow payload
- Never trigger Flow on test/preview quiz completions

