  quiz_score: number;
  customer_email?: string;
  recommended_product_ids: string;    // comma-separated GIDs
}

interface HighValueLeadPayload {
  customer_email: string;
  quiz_score: number;
  quiz_id: string;
  quiz_title: string;
  top_product_id: string;
}

interface EmailCapturedPayload {
  customer_email: string;
  quiz_title: string;
  quiz_id: string;
}

export async function triggerQuizCompleted(
  admin: AdminApiContext,
  payload: QuizCompletedPayload
): Promise<void> {
  await sendFlowTrigger(admin, "quiz-completed", payload);
}

export async function triggerHighValueLead(
  admin: AdminApiContext,
  payload: HighValueLeadPayload
): Promise<void> {
  await sendFlowTrigger(admin, "high-value-lead", payload);
}

export async function triggerEmailCaptured(
  admin: AdminApiContext,
  payload: EmailCapturedPayload
): Promise<void> {
  await sendFlowTrigger(admin, "email-captured", payload);
}

async function sendFlowTrigger(
  admin: AdminApiContext,
  handle: string,
  payload: Record<string, unknown>
): Promise<void> {
  try {
    const resp = await admin.graphql(FLOW_TRIGGER_MUTATION, {
      variables: { handle, payload }
    });
    const { data } = await resp.json();

    const errors = data?.flowTriggerReceive?.userErrors ?? [];
    if (errors.length > 0) {
      // Log but don't throw — Flow triggers are best-effort
      console.error(`Flow trigger "${handle}" userErrors:`, errors);
    }
  } catch (err) {
    // Never block quiz completion for Flow trigger failures
    console.error(`Flow trigger "${handle}" failed (non-blocking):`, err);
  }
}
```

## QUIZ COMPLETION INTEGRATION POINT

```typescript
// In quiz completion handler — fire all integrations
import { triggerQuizCompleted, triggerHighValueLead, triggerEmailCaptured } from "~/utils/shopify-flow.server";

async function fireIntegrations(
  admin: AdminApiContext,
  shop: string,
  response: {
    quizId: string;
    quizTitle: string;
    resultPage: string;
    score: number;
    email?: string;
    recommendedProductGids: string[];
  },
  settings: { highValueLeadThreshold?: number }
) {
  const productIdsCsv = response.recommendedProductGids.join(",");

  // Fire QuizCompleted trigger
  triggerQuizCompleted(admin, {
    quiz_id: response.quizId,
    quiz_title: response.quizTitle,
    result_page: response.resultPage,
    quiz_score: response.score,
    customer_email: response.email,
    recommended_product_ids: productIdsCsv,
  });

  // Fire EmailCaptured trigger if email was provided
  if (response.email) {
    triggerEmailCaptured(admin, {
      customer_email: response.email,
      quiz_title: response.quizTitle,
      quiz_id: response.quizId,
    });
  }

  // Fire HighValueLead if score exceeds threshold
  const threshold = settings.highValueLeadThreshold ?? 70;
  if (response.score >= threshold && response.email) {
    triggerHighValueLead(admin, {
      customer_email: response.email,
      quiz_score: response.score,
      quiz_id: response.quizId,
      quiz_title: response.quizTitle,
      top_product_id: response.recommendedProductGids[0] ?? "",
    });
  }
}
```

