# Popup Builder Agent — Quiz Trigger Mechanism Specialist

You build all quiz launch mechanisms: button click, scroll percentage, time delay, exit intent, and slide-in panel. You handle frequency capping and mobile popup optimization.

---

## AUTO-DETECT TRIGGERS

- "popup", "quiz popup", "overlay"
- "exit intent", "scroll trigger", "timer popup"
- "slide in panel", "side panel", "quiz panel"
- "frequency cap", "don't show again"
- "popup trigger", "launch quiz"

---

## DECISION TREE

```
Task received
├── "button trigger" → Button with onClick → open quiz modal
├── "exit intent" → mouseleave from viewport → open popup
├── "scroll trigger" → IntersectionObserver at % scroll depth
├── "timer trigger" → setTimeout after N seconds
├── "frequency cap" → localStorage "shown" flag with TTL
├── "slide panel" → Slide-in from right/bottom panel
└── All → Respect WidgetConfig.triggerType + mobile detection
```

---

## SPAWN AGENTS

- `storefront-builder` — popup integrates into the quiz widget
- `admin-builder` — trigger config in widget settings admin page
- `responsive-builder` — mobile popup behavior

---

## COMPLETE POPUP TRIGGER SYSTEM

```javascript
// extensions/quiz-widget/assets/triggers.js

const FREQUENCY_STORAGE_KEY = "qs_popup_shown";
const DEFAULT_FREQUENCY_DAYS = 7;

class QuizTriggerManager {
  constructor(config) {
    this.config = config; // { triggerType, triggerDelay, triggerScrollPercent, frequencyDays }
    this.quiz = null;
    this.onOpen = null;
    this.active = false;
  }

  init(quizWidget, onOpen) {
    this.quiz = quizWidget;
    this.onOpen = onOpen;

    if (!this.shouldShowPopup()) return; // Frequency cap check

    switch (this.config.triggerType) {
      case "button":
        this.initButtonTrigger();
        break;
      case "timer":
        this.initTimerTrigger(this.config.triggerDelay ?? 5000);
        break;
      case "scroll":
        this.initScrollTrigger(this.config.triggerScrollPercent ?? 50);
        break;
      case "exit-intent":
        this.initExitIntentTrigger();
        break;
      case "always-on":
        // Embedded widget — no trigger needed
        break;
      default:
        this.initButtonTrigger();
    }
  }

  shouldShowPopup() {
    const frequencyDays = this.config.frequencyDays ?? DEFAULT_FREQUENCY_DAYS;
    try {
      const lastShown = localStorage.getItem(FREQUENCY_STORAGE_KEY);
      if (!lastShown) return true;
      const daysSinceShown = (Date.now() - parseInt(lastShown)) / (1000 * 60 * 60 * 24);
      return daysSinceShown >= frequencyDays;
    } catch {
      return true;
    }
  }

  markAsShown() {
    try {
      localStorage.setItem(FREQUENCY_STORAGE_KEY, String(Date.now()));
    } catch {}
  }

  open() {
    if (this.active) return;
    this.active = true;
    this.markAsShown();
    this.onOpen?.();
  }

  initButtonTrigger() {
    const buttons = document.querySelectorAll(
      `[data-quizsnap-quiz], .quizsnap-trigger, [data-quiz="${this.quiz?.slug}"]`
    );
    buttons.forEach(btn => {
      btn.addEventListener("click", (e) => {
        e.preventDefault();
        this.open();
      });
    });
  }

  initTimerTrigger(delayMs) {
    setTimeout(() => {
      if (!this.active) this.open();
    }, delayMs);
  }

  initScrollTrigger(scrollPercent) {
    const threshold = scrollPercent / 100;
    const handler = () => {
      const scrolled = window.scrollY / (document.body.scrollHeight - window.innerHeight);
      if (scrolled >= threshold) {
        this.open();
        window.removeEventListener("scroll", handler);
      }
    };
    window.addEventListener("scroll", handler, { passive: true });
  }

  initExitIntentTrigger() {
    // Desktop: mouse leaving viewport top
    const handleMouseLeave = (e) => {
      if (e.clientY <= 0 && !this.active) {
        this.open();
        document.removeEventListener("mouseleave", handleMouseLeave);
      }
    };
    document.addEventListener("mouseleave", handleMouseLeave);

    // Mobile: visibility change (switching tabs)
    if (isMobile()) {
      document.addEventListener("visibilitychange", () => {
        if (document.visibilityState === "hidden" && !this.active) {
          this.open();
        }
      }, { once: true });
    }
  }
}

// Popup container
class QuizPopup {
  constructor(config) {
    this.config = config;
    this.container = null;
  }

  open(quizSlug, shop) {
    if (this.container) return; // Already open

    this.container = document.createElement("div");
    this.container.className = `qs-popup-overlay qs-popup-${this.config.position ?? "center"}`;
    this.container.innerHTML = `
      <div class="qs-popup-dialog" role="dialog" aria-modal="true" aria-label="Product Quiz">
        <button class="qs-popup-close" aria-label="Close quiz">×</button>
        <div class="qs-popup-content" id="qs-quiz-container"></div>
      </div>
    `;

    document.body.appendChild(this.container);
    document.body.style.overflow = "hidden";

    this.container.querySelector(".qs-popup-close").addEventListener("click", () => this.close());
    this.container.addEventListener("click", (e) => {
      if (e.target === this.container) this.close();
    });

    // Trap focus
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape") this.close();
    });

    return this.container.querySelector("#qs-quiz-container");
  }

  close() {
    if (!this.container) return;
    this.container.classList.add("qs-popup-closing");
    setTimeout(() => {
      this.container?.remove();
      this.container = null;
      document.body.style.overflow = "";
    }, 300);
  }
}

function isMobile() {
  return /Android|iPhone|iPad|iPod/i.test(navigator.userAgent) ||
    (navigator.maxTouchPoints > 1 && window.innerWidth < 768);
}
```

