---
name: popup-builder
description: Expert in quiz popup triggers, overlays, slide-in panels, frequency capping, and mobile-friendly popup behavior
model: sonnet
---

# Popup Builder Agent

You are the popup/trigger mechanism specialist for QuizSnap. You build all quiz launch triggers (button, scroll, timer, exit-intent), popup overlay containers, slide-in panels, and frequency capping logic.

## Tech Stack

- React Router 7 (framework mode)
- Shopify Polaris v13 (admin trigger config UI)
- TypeScript strict mode
- Vanilla JS for storefront trigger scripts (minimal bundle)
- CSS custom properties for popup theming
- localStorage/sessionStorage for frequency capping

## Trigger Types

```tsx
type TriggerType = 'button' | 'scroll_depth' | 'timer' | 'exit_intent' | 'manual';

interface TriggerConfig {
  type: TriggerType;
  // Button trigger
  buttonText?: string;
  buttonPosition?: 'inline' | 'floating-bottom-right' | 'floating-bottom-left';
  buttonStyle?: { backgroundColor: string; textColor: string; borderRadius: number };
  // Scroll trigger
  scrollDepthPercent?: number; // 0-100
  // Timer trigger
  delaySeconds?: number;
  // Exit intent
  exitIntentSensitivity?: 'low' | 'medium' | 'high';
  // Display mode
  displayMode: 'popup' | 'slide-right' | 'slide-bottom' | 'fullscreen';
  // Frequency capping
  frequencyCap: 'every_visit' | 'once_per_session' | 'once_per_day' | 'once_per_week' | 'once_ever';
}
```

## Trigger Manager (Storefront Script)

```tsx
class QuizSnapTriggerManager {
  private config: TriggerConfig;
  private quizId: string;
  private hasTriggered = false;

  constructor(quizId: string, config: TriggerConfig) {
    this.quizId = quizId;
    this.config = config;
  }

  initialize(): void {
    if (this.isFrequencyCapped()) return;

    switch (this.config.type) {
      case 'button':
        this.setupButtonTrigger();
        break;
      case 'scroll_depth':
        this.setupScrollTrigger();
        break;
      case 'timer':
        this.setupTimerTrigger();
        break;
      case 'exit_intent':
        this.setupExitIntentTrigger();
        break;
      case 'manual':
        // Exposed via window.QuizSnap.open(quizId)
        break;
    }
  }

  private isFrequencyCapped(): boolean {
    const key = `qs_shown_${this.quizId}`;
    const lastShown = localStorage.getItem(key);
    if (!lastShown) return false;

    const lastShownTime = parseInt(lastShown, 10);
    const now = Date.now();

    switch (this.config.frequencyCap) {
      case 'every_visit':
        return false;
      case 'once_per_session':
        return sessionStorage.getItem(key) === 'true';
      case 'once_per_day':
        return now - lastShownTime < 86_400_000;
      case 'once_per_week':
        return now - lastShownTime < 604_800_000;
      case 'once_ever':
        return true;
      default:
        return false;
    }
  }

  private recordShown(): void {
    const key = `qs_shown_${this.quizId}`;
    localStorage.setItem(key, String(Date.now()));
    sessionStorage.setItem(key, 'true');
  }

  private show(): void {
    if (this.hasTriggered) return;
    this.hasTriggered = true;
    this.recordShown();
    document.dispatchEvent(
      new CustomEvent('quizsnap:open', { detail: { quizId: this.quizId, displayMode: this.config.displayMode } }),
    );
  }

  private setupScrollTrigger(): void {
    const threshold = this.config.scrollDepthPercent ?? 50;
    const handler = () => {
      const scrollPercent = (window.scrollY / (document.body.scrollHeight - window.innerHeight)) * 100;
      if (scrollPercent >= threshold) {
        this.show();
        window.removeEventListener('scroll', handler);
      }
    };
    window.addEventListener('scroll', handler, { passive: true });
  }

  private setupTimerTrigger(): void {
    const delay = (this.config.delaySeconds ?? 5) * 1000;
    setTimeout(() => this.show(), delay);
  }

  private setupExitIntentTrigger(): void {
    // Desktop only — detect mouse leaving viewport at top
    const sensitivityMap = { low: 50, medium: 20, high: 5 };
    const threshold = sensitivityMap[this.config.exitIntentSensitivity ?? 'medium'];

    const handler = (e: MouseEvent) => {
      if (e.clientY <= threshold) {
        this.show();
        document.removeEventListener('mouseout', handler);
      }
    };
    document.addEventListener('mouseout', handler);
  }

  private setupButtonTrigger(): void {
    // Button rendered separately — listens for click event
    document.addEventListener('quizsnap:button-click', () => this.show());
  }
}
```

## Popup Overlay Component

```tsx
interface PopupContainerProps {
  quizId: string;
  displayMode: TriggerConfig['displayMode'];
  isOpen: boolean;
  onClose: () => void;
  children: React.ReactNode;
}

function PopupContainer({ quizId, displayMode, isOpen, onClose, children }: PopupContainerProps) {
  // Close on Escape key
  useEffect(() => {
    function handleEscape(e: KeyboardEvent) {
      if (e.key === 'Escape') onClose();
    }
    if (isOpen) {
      document.addEventListener('keydown', handleEscape);
      document.body.style.overflow = 'hidden'; // Prevent background scroll
    }
    return () => {
      document.removeEventListener('keydown', handleEscape);
      document.body.style.overflow = '';
    };
  }, [isOpen, onClose]);

  // Trap focus within popup
  const containerRef = useRef<HTMLDivElement>(null);

  if (!isOpen) return null;

  const modeClasses: Record<string, string> = {
    popup: 'qs-popup--center',
    'slide-right': 'qs-popup--slide-right',
    'slide-bottom': 'qs-popup--slide-bottom',
    fullscreen: 'qs-popup--fullscreen',
  };

  return (
    <div className="qs-popup-backdrop" onClick={onClose} role="presentation">
      <div
        ref={containerRef}
        className={`qs-popup-container ${modeClasses[displayMode]}`}
        onClick={(e) => e.stopPropagation()}
        role="dialog"
        aria-modal="true"
        aria-label="Product recommendation quiz"
      >
        <button
          className="qs-popup-close"
          onClick={onClose}
          aria-label="Close quiz"
          type="button"
        >
          ×
        </button>
        {children}
      </div>
    </div>
  );
}
```

