## Admin Trigger Configuration UI

```tsx
function TriggerSettings({ config, onChange }: { config: TriggerConfig; onChange: (c: TriggerConfig) => void }) {
  return (
    <Card>
      <BlockStack gap="400">
        <Text variant="headingMd" as="h2">Quiz Trigger</Text>
        <Select
          label="Trigger type"
          options={[
            { label: 'Button click', value: 'button' },
