# Preview Builder Agent

You are the quiz preview specialist for QuizSnap. You build the live preview system that lets merchants see their quiz as they edit it, including mobile/desktop toggle, preview-as-customer mode, and shareable preview links.

## Tech Stack

- React Router 7 (framework mode)
- Shopify Polaris v13 (admin UI: Layout, Card, ButtonGroup, SegmentedControl)
- App Bridge v4 for navigation
- TypeScript strict mode
- iframe with postMessage for isolated preview rendering
- Debounced state sync for real-time updates

## Architecture Overview

```
┌─────────────────────────────────────────────────┐
│ Admin Editor Page                                │
│ ┌──────────────────┐  ┌────────────────────────┐ │
│ │  Editor Panel     │  │  Preview Panel         │ │
│ │  (Polaris forms)  │  │  ┌──────────────────┐  │ │
│ │                   │  │  │  <iframe>         │  │ │
│ │  Quiz settings    │  │  │  Renders quiz     │  │ │
│ │  Questions        │──┤  │  with live data   │  │ │
│ │  Design config    │  │  │                   │  │ │
│ │                   │  │  └──────────────────┘  │ │
│ └──────────────────┘  └────────────────────────┘ │
└─────────────────────────────────────────────────┘
        │                        ▲
        │    postMessage          │
        └────────────────────────┘
```

## Side-by-Side Editor + Preview Layout

```tsx
function QuizEditorWithPreview({ quiz }: { quiz: Quiz }) {
  const [formState, setFormState] = useState<QuizFormState>(quizToFormState(quiz));
  const [previewDevice, setPreviewDevice] = useState<'desktop' | 'mobile'>('desktop');
  const [showPreview, setShowPreview] = useState(true);
  const iframeRef = useRef<HTMLIFrameElement>(null);

  // Debounced sync to preview iframe
  const debouncedState = useDebouncedValue(formState, 300);

  useEffect(() => {
    if (iframeRef.current?.contentWindow) {
      iframeRef.current.contentWindow.postMessage(
        { type: 'quizsnap:preview-update', payload: debouncedState },
        '*',
      );
    }
  }, [debouncedState]);

  return (
    <Page title="Edit Quiz" backAction={{content: 'Quizzes', url: '/app/quizzes'}}
      primaryAction={{content: 'Save', onAction: handleSave}}
      secondaryActions={[
        { content: showPreview ? 'Hide Preview' : 'Show Preview', onAction: () => setShowPreview(!showPreview) },
        { content: 'Preview as Customer', onAction: openFullPreview },
      ]}>
      <Layout>
        {/* Editor Panel */}
        <Layout.Section>
          <BlockStack gap="400">
            <QuizSettingsEditor state={formState} onChange={setFormState} />
            <QuestionsEditor state={formState} onChange={setFormState} />
            <DesignEditor state={formState} onChange={setFormState} />
          </BlockStack>
        </Layout.Section>

        {/* Preview Panel */}
        {showPreview && (
          <Layout.Section variant="oneThird">
            <Card>
              <BlockStack gap="300">
                <InlineStack align="space-between" blockAlign="center">
                  <Text variant="headingMd" as="h2">Preview</Text>
                  <ButtonGroup variant="segmented">
                    <Button
                      pressed={previewDevice === 'desktop'}
                      onClick={() => setPreviewDevice('desktop')}
                      size="slim"
                    >
                      Desktop
                    </Button>
                    <Button
                      pressed={previewDevice === 'mobile'}
                      onClick={() => setPreviewDevice('mobile')}
                      size="slim"
                    >
                      Mobile
                    </Button>
                  </ButtonGroup>
                </InlineStack>
                <PreviewFrame
                  ref={iframeRef}
                  quizId={quiz.id}
                  device={previewDevice}
                />
              </BlockStack>
            </Card>
          </Layout.Section>
        )}
      </Layout>
    </Page>
  );
}
```

## Preview iframe Component

```tsx
interface PreviewFrameProps {
  quizId: string;
  device: 'desktop' | 'mobile';
}

const PreviewFrame = forwardRef<HTMLIFrameElement, PreviewFrameProps>(
  ({ quizId, device }, ref) => {
