PreviewFrame.displayName = 'PreviewFrame';
```

## Preview Route (Inside iframe)

```tsx
// app/routes/app.quizzes.$id.preview.tsx
import type { LoaderFunctionArgs } from 'react-router';

export async function loader({ params }: LoaderFunctionArgs) {
  const quiz = await prisma.quiz.findUnique({
    where: { id: params.id },
    include: { questions: { include: { answers: true }, orderBy: { position: 'asc' } } },
  });
  return json({ quiz });
}

export default function QuizPreview() {
  const { quiz } = useLoaderData<typeof loader>();
  const [previewState, setPreviewState] = useState<QuizFormState | null>(null);

  // Listen for real-time updates from parent editor
  useEffect(() => {
    function handleMessage(event: MessageEvent) {
      if (event.data?.type === 'quizsnap:preview-update') {
        setPreviewState(event.data.payload);
      }
      if (event.data?.type === 'quizsnap:preview-navigate') {
        setCurrentQuestion(event.data.payload.questionIndex);
      }
    }
    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, []);

  const activeState = previewState ?? quizToFormState(quiz);

  return (
    <div className="qs-preview-root">
      <QuizRenderer state={activeState} isPreview={true} />
    </div>
  );
}
```

## Debounced State Hook

```tsx
function useDebouncedValue<T>(value: T, delayMs: number): T {
  const [debounced, setDebounced] = useState(value);

  useEffect(() => {
    const timeout = setTimeout(() => setDebounced(value), delayMs);
    return () => clearTimeout(timeout);
  }, [value, delayMs]);

  return debounced;
}
```

## Preview All States

```tsx
// Navigate preview to specific states
function PreviewStateControls({ iframeRef }: { iframeRef: React.RefObject<HTMLIFrameElement> }) {
  function navigateTo(state: string, data?: Record<string, unknown>) {
    iframeRef.current?.contentWindow?.postMessage(
      { type: 'quizsnap:preview-navigate', payload: { state, ...data } },
      '*',
    );
  }

  return (
    <InlineStack gap="200" wrap>
      <Button size="slim" onClick={() => navigateTo('welcome')}>Welcome</Button>
      <Button size="slim" onClick={() => navigateTo('question', { questionIndex: 0 })}>Q1</Button>
      <Button size="slim" onClick={() => navigateTo('question', { questionIndex: 1 })}>Q2</Button>
      <Button size="slim" onClick={() => navigateTo('loading')}>Loading</Button>
      <Button size="slim" onClick={() => navigateTo('results')}>Results</Button>
    </InlineStack>
  );
}
```

## Shareable Preview Link

```tsx
// Generate a public preview link with a token
async function generatePreviewLink(quizId: string): Promise<string> {
  const token = crypto.randomUUID();
  await prisma.quizPreviewToken.upsert({
    where: { quizId },
    create: { quizId, token, expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000) },
    update: { token, expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000) },
  });
  const shop = await getShopDomain();
  return `https://${shop}/apps/quizsnap/preview/${quizId}?token=${token}`;
}

// Admin UI for sharing
function SharePreviewButton({ quizId }: { quizId: string }) {
  const fetcher = useFetcher();
  const [copied, setCopied] = useState(false);

  async function handleShare() {
    fetcher.submit({ intent: 'generate-preview-link' }, { method: 'POST' });
  }

  useEffect(() => {
    if (fetcher.data?.previewUrl) {
      navigator.clipboard.writeText(fetcher.data.previewUrl).then(() => {
        setCopied(true);
        shopify.toast.show('Preview link copied to clipboard');
        setTimeout(() => setCopied(false), 3000);
      });
    }
  }, [fetcher.data]);

  return (
    <Button
      onClick={handleShare}
      loading={fetcher.state !== 'idle'}
      icon={copied ? ClipboardCheckIcon : LinkIcon}
    >
      {copied ? 'Copied!' : 'Share Preview'}
    </Button>
  );
}
```

## Quiz Renderer (Used in Preview + Storefront)

```tsx
interface QuizRendererProps {
  state: QuizFormState;
  isPreview: boolean;
  onComplete?: (answers: Record<string, string>) => void;
}

function QuizRenderer({ state, isPreview, onComplete }: QuizRendererProps) {
  const [currentView, setCurrentView] = useState<'welcome' | 'question' | 'loading' | 'results'>('welcome');
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswers, setSelectedAnswers] = useState<Record<string, string>>({});

  return (
    <div className="qs-quiz" style={{ '--qs-accent': state.design.accentColor } as React.CSSProperties}>
      {currentView === 'welcome' && (
        <WelcomeScreen config={state.welcome} onStart={() => setCurrentView('question')} />
      )}
      {currentView === 'question' && (
        <>
          <QuizProgress config={state.progressBar} />
          <QuestionView
            question={state.questions[currentQuestionIndex]}
            selectedAnswer={selectedAnswers[state.questions[currentQuestionIndex].id]}
            onAnswer={(answerId) => {
              setSelectedAnswers((prev) => ({
                ...prev,
                [state.questions[currentQuestionIndex].id]: answerId,
              }));
            }}
            onNext={() => {
              if (currentQuestionIndex < state.questions.length - 1) {
                setCurrentQuestionIndex((i) => i + 1);
              } else {
                setCurrentView('loading');
                if (!isPreview) onComplete?.(selectedAnswers);
              }
            }}
            onBack={() => setCurrentQuestionIndex((i) => Math.max(0, i - 1))}
          />
        </>
      )}
      {currentView === 'loading' && (
        <LoadingScreen onDone={() => setCurrentView('results')} />
      )}
      {currentView === 'results' && (
        <ResultsScreen config={state.results} isPreview={isPreview} />
      )}
    </div>
  );
}
```

## Collaboration Protocol

- **ui-specialist**: Editor panel uses Polaris forms — preview panel is a separate Layout.Section
- **progress-bar-builder**: QuizProgress component renders inside preview QuizRenderer
- **product-card-builder**: ResultsScreen renders product cards — share product card component
- **responsive-builder**: Preview must show both mobile and desktop viewports accurately
- **popup-builder**: Preview shows quiz in all display modes (popup, slide-in, fullscreen)
- **image-choice-builder**: Image choice grid renders inside QuestionView in preview

## Validation Checklist

- [ ] postMessage communication uses specific type string (not generic)
- [ ] iframe has `sandbox="allow-scripts allow-same-origin"` for security
- [ ] Preview updates are debounced (300ms) to avoid excessive re-renders
- [ ] Mobile preview uses 375px width with phone-like border
- [ ] Desktop preview uses full available width
- [ ] Preview navigation buttons allow jumping to any state (welcome, Q1, Q2, loading, results)
- [ ] Preview link expires after 7 days
- [ ] Preview mode prevents actual form submissions and cart additions
- [ ] Transition between mobile/desktop is animated smoothly
- [ ] Preview re-renders immediately when merchant changes design settings

