## FUNNEL ANALYSIS QUERY

```typescript
// app/services/conversion.server.ts
export async function getConversionFunnel(shop: string, quizId: string, days: number = 30) {
  const since = new Date(Date.now() - days * 24 * 60 * 60 * 1000);

  const [starts, completions, cartAdds, orders] = await Promise.all([
    db.analyticsEvent.count({ where: { shop, quizId, type: "quiz_started", createdAt: { gte: since } } }),
    db.analyticsEvent.count({ where: { shop, quizId, type: "quiz_completed", createdAt: { gte: since } } }),
    db.analyticsEvent.count({ where: { shop, quizId, type: "add_to_cart", createdAt: { gte: since } } }),
    db.analyticsEvent.count({ where: { shop, quizId, type: "order_placed", createdAt: { gte: since } } }),
  ]);

  return {
    starts,
    completions,
    completionRate: starts > 0 ? Math.round((completions / starts) * 100) : 0,
    cartAdds,
    cartRate: completions > 0 ? Math.round((cartAdds / completions) * 100) : 0,
    orders,
    purchaseRate: cartAdds > 0 ? Math.round((orders / cartAdds) * 100) : 0,
    overallConversion: starts > 0 ? Math.round((orders / starts) * 100) : 0,
  };
}

// Find questions with highest drop-off
export async function getQuestionDropOffRate(shop: string, quizId: string) {
  const questions = await db.question.findMany({
    where: { quizId, quiz: { shop } },
    orderBy: { position: "asc" },
    select: { id: true, title: true, position: true },
  });

  const dropOffData = await Promise.all(
    questions.map(async (q) => {
      const views = await db.analyticsEvent.count({
        where: { shop, quizId, type: "question_viewed", metadata: { contains: q.id } },
      });
      const answers = await db.analyticsEvent.count({
        where: { shop, quizId, type: "question_answered", metadata: { contains: q.id } },
      });
      return {
        questionId: q.id,
        title: q.title,
        position: q.position,
        viewCount: views,
        answerCount: answers,
        dropOffRate: views > 0 ? Math.round(((views - answers) / views) * 100) : 0,
      };
    })
  );

  return dropOffData.sort((a, b) => b.dropOffRate - a.dropOffRate);
}
```

