function detectLocale() {
  // 1. Check Shopify locale meta tag
  const shopifyLocale = document.documentElement.lang ||
    document.querySelector("meta[name=\\'shopify-locale\\']")?.content;
  if (shopifyLocale) return shopifyLocale.split("-")[0]; // "fr-FR" → "fr"

