```typescript
// app/services/image.server.ts

/**
 * Transform Shopify CDN image URLs to add size/format parameters
 * Supports: Shopify product images, Files API images
 */
export function optimizeShopifyImageUrl(
  url: string | null,
  options: {
    width?: number;
    height?: number;
    format?: "webp" | "jpg" | "png";
    crop?: "center" | "top" | "bottom";
  } = {}
): string | null {
  if (!url) return null;

  // Check if it\'s a Shopify CDN URL
  if (!url.includes("cdn.shopify.com")) return url;

  // Remove existing size parameters
  const baseUrl = url.replace(/_(\\d+)x(\\d+)?(\\.\\w+)?$/, "$3").replace(/\\.webp$/, "");

  // Build size string
  const { width = 600, height, format = "webp", crop } = options;
  const sizeStr = height ? `${width}x${height}` : `${width}x`;
  const cropStr = crop ? `_crop_${crop}` : "";
  const ext = format === "webp" ? ".webp" : ".jpg";

  // Insert size before extension
  return baseUrl.replace(/(\\.\\w+)$/, `_${sizeStr}${cropStr}${ext}`);
}

// Product card optimal sizes
export const IMAGE_SIZES = {
