## LAZY LOADING WIDGET IMPLEMENTATION

```javascript
// extensions/quiz-widget/assets/imageLoader.js

function initLazyLoading() {
  if (!("IntersectionObserver" in window)) {
    // Fallback: load all images immediately
    document.querySelectorAll("img[data-src]").forEach(img => {
      img.src = img.dataset.src;
    });
    return;
  }

  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (!entry.isIntersecting) return;
      const img = entry.target;
      if (img.dataset.src) {
        img.src = img.dataset.src;
        img.removeAttribute("data-src");
        img.classList.add("qs-img-loaded");
      }
      observer.unobserve(img);
    });
  }, { rootMargin: "50px" }); // Pre-load 50px before visible

  document.querySelectorAll("img[data-src]").forEach(img => observer.observe(img));
}

// Render lazy image with placeholder
function renderLazyImage(src, alt, aspectRatio = "1/1") {
  if (!src) {
    return `<div class="qs-img-placeholder" style="aspect-ratio:${aspectRatio}"></div>`;
  }

  // Optimize Shopify CDN URL
  const optimizedSrc = optimizeImageUrl(src, 400);

  return `
    <div class="qs-img-wrapper" style="aspect-ratio:${aspectRatio}">
      <div class="qs-img-skeleton"></div>
      <img
        data-src="${escapeAttr(optimizedSrc)}"
        src="data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw=="
        alt="${escapeAttr(alt)}"
        loading="lazy"
        class="qs-product-image"
        onload="this.previousElementSibling.remove(); this.classList.add(\\'qs-img-loaded\\')"
      >
    </div>
  `;
}

function optimizeImageUrl(url, width) {
  if (!url || !url.includes("cdn.shopify.com")) return url;
  return url.replace(/(\\.(jpg|jpeg|png|gif|webp))(?:\\?|$)/i, \`_\${width}x.webp\`);
}
```

