## VERSION MANAGEMENT SERVICE

```typescript
// app/services/versions.server.ts

export async function saveQuizVersion(quizId: string, shop: string, label?: string): Promise<void> {
  const quiz = await db.quiz.findUnique({
    where: { id: quizId },
    include: {
      questions: { include: { answers: true }, orderBy: { position: "asc" } },
      resultPages: { orderBy: { position: "asc" } },
    },
  });
  if (!quiz || quiz.shop !== shop) return;

  const latestVersion = await db.quizVersion.findFirst({
    where: { quizId },
    orderBy: { version: "desc" },
    select: { version: true },
  });

  await db.quizVersion.create({
    data: {
      quizId,
      version: (latestVersion?.version ?? 0) + 1,
      snapshot: JSON.stringify(quiz),
      label: label ?? new Date().toLocaleDateString(),
    },
  });

  // Keep only last 20 versions
  const oldVersions = await db.quizVersion.findMany({
    where: { quizId },
    orderBy: { version: "desc" },
    skip: 20,
    select: { id: true },
  });
  if (oldVersions.length > 0) {
    await db.quizVersion.deleteMany({ where: { id: { in: oldVersions.map(v => v.id) } } });
  }
}

export async function restoreQuizVersion(quizId: string, versionId: string, shop: string): Promise<void> {
  const version = await db.quizVersion.findUnique({ where: { id: versionId } });
  if (!version || version.quizId !== quizId) throw new Error("Version not found");

  const quiz = await db.quiz.findUnique({ where: { id: quizId } });
  if (!quiz || quiz.shop !== shop) throw new Error("Unauthorized");

  const snapshot = JSON.parse(version.snapshot);

  // Save current state as "before restore" version first
  await saveQuizVersion(quizId, shop, "Before restore");

  await db.$transaction(async (tx) => {
    // Update quiz
    await tx.quiz.update({
      where: { id: quizId },
      data: { title: snapshot.title, description: snapshot.description,
        settings: snapshot.settings, styling: snapshot.styling },
    });

    // Delete and recreate questions
    await tx.question.deleteMany({ where: { quizId } });
    for (const q of snapshot.questions ?? []) {
      const question = await tx.question.create({ data: { ...q, quizId, id: undefined } });
      for (const a of q.answers ?? []) {
        await tx.answer.create({ data: { ...a, questionId: question.id, id: undefined } });
      }
    }
  });
}
```

