// Keyboard navigation for quiz answers
function makeAnswersAccessible(answerContainer) {
  const answers = answerContainer.querySelectorAll(".qs-answer-option");

  answers.forEach((answer, index) => {
    answer.setAttribute("role", "radio");
    answer.setAttribute("tabindex", index === 0 ? "0" : "-1");
    answer.setAttribute("aria-checked", "false");

    answer.addEventListener("keydown", (e) => {
      switch (e.key) {
        case "Enter":
        case " ":
          e.preventDefault();
          answer.click();
          break;
        case "ArrowDown":
        case "ArrowRight":
          e.preventDefault();
          const next = answers[index + 1] ?? answers[0];
          next.focus();
          break;
        case "ArrowUp":
        case "ArrowLeft":
          e.preventDefault();
          const prev = answers[index - 1] ?? answers[answers.length - 1];
          prev.focus();
          break;
      }
    });
