```typescript
// app/services/reports.server.ts
export interface QuizPerformanceReport {
  period: { from: Date; to: Date };
  quizzes: Array<{
    quizId: string;
    title: string;
    status: string;
    starts: number;
    completions: number;
    completionRate: number;
    cartAdds: number;
    cartRate: number;
    revenue: number;
  }>;
  totals: {
    totalStarts: number;
    totalCompletions: number;
    avgCompletionRate: number;
    totalRevenue: number;
    topQuizId: string | null;
  };
}

export async function generatePerformanceReport(
  shop: string,
  from: Date,
  to: Date
): Promise<QuizPerformanceReport> {
  const quizzes = await db.quiz.findMany({
    where: { shop },
    select: { id: true, title: true, status: true },
  });

  const quizReports = await Promise.all(
    quizzes.map(async (quiz) => {
      const [starts, completions, cartAdds] = await Promise.all([
        db.analyticsEvent.count({ where: { shop, quizId: quiz.id, type: "quiz_started", createdAt: { gte: from, lte: to } } }),
        db.analyticsEvent.count({ where: { shop, quizId: quiz.id, type: "quiz_completed", createdAt: { gte: from, lte: to } } }),
        db.analyticsEvent.count({ where: { shop, quizId: quiz.id, type: "add_to_cart", createdAt: { gte: from, lte: to } } }),
      ]);

      const revenueAgg = await db.analyticsEvent.aggregate({
        where: { shop, quizId: quiz.id, type: "order_placed", createdAt: { gte: from, lte: to } },
        _sum: { value: true },
      });

      return {
        quizId: quiz.id,
        title: quiz.title,
        status: quiz.status,
        starts,
        completions,
        completionRate: starts > 0 ? Math.round((completions / starts) * 100) : 0,
        cartAdds,
        cartRate: completions > 0 ? Math.round((cartAdds / completions) * 100) : 0,
        revenue: revenueAgg._sum.value ?? 0,
      };
    })
  );

  const totals = {
    totalStarts: quizReports.reduce((s, q) => s + q.starts, 0),
    totalCompletions: quizReports.reduce((s, q) => s + q.completions, 0),
    avgCompletionRate: quizReports.length > 0
      ? Math.round(quizReports.reduce((s, q) => s + q.completionRate, 0) / quizReports.length)
      : 0,
    totalRevenue: quizReports.reduce((s, q) => s + q.revenue, 0),
    topQuizId: quizReports.sort((a, b) => b.completions - a.completions)[0]?.quizId ?? null,
  };

  return { period: { from, to }, quizzes: quizReports, totals };
}
```

