// When visitor lands via shared link (/share/:shareId)
// Track the original sharer session + the new completion
export async function trackSharedVisit(shareId: string, newSessionId: string): Promise<void> {
  const originalResponse = await db.quizResponse.findFirst({
    where: { shareId },
    select: { quizId: true, shop: true, sessionId: true },
  });
  if (!originalResponse) return;

  await db.analyticsEvent.create({
    data: {
      quizId: originalResponse.quizId,
      shop: originalResponse.shop,
      type: "share_visit",
      sessionId: newSessionId,
      metadata: JSON.stringify({
        originalSessionId: originalResponse.sessionId,
        shareId,
      }),
    },
  });
}

// Viral coefficient: shares that led to new completions / total completions
export async function getViralCoefficient(shop: string, quizId: string, days: number = 30): Promise<number> {
  const since = new Date(Date.now() - days * 24 * 60 * 60 * 1000);
  const [shareVisits, totalCompletions] = await Promise.all([
    db.analyticsEvent.count({ where: { shop, quizId, type: "share_visit", createdAt: { gte: since } } }),
    db.analyticsEvent.count({ where: { shop, quizId, type: "quiz_completed", createdAt: { gte: since } } }),
  ]);
  return totalCompletions > 0 ? Math.round((shareVisits / totalCompletions) * 100) / 100 : 0;
}
