## IN-MEMORY CACHE IMPLEMENTATION

```typescript
// app/services/cache.server.ts

interface CacheEntry<T> {
  value: T;
  expiresAt: number;
}

class SimpleCache<T> {
  private store = new Map<string, CacheEntry<T>>();
  private readonly defaultTtlMs: number;

  constructor(defaultTtlSeconds: number = 60) {
    this.defaultTtlMs = defaultTtlSeconds * 1000;
    // Cleanup expired entries every minute
    setInterval(() => this.cleanup(), 60 * 1000);
  }

  get(key: string): T | null {
    const entry = this.store.get(key);
    if (!entry) return null;
    if (Date.now() > entry.expiresAt) {
      this.store.delete(key);
      return null;
    }
    return entry.value;
  }

  set(key: string, value: T, ttlSeconds?: number): void {
    const ttlMs = (ttlSeconds ?? 0) * 1000 || this.defaultTtlMs;
    this.store.set(key, { value, expiresAt: Date.now() + ttlMs });
  }

  delete(key: string): void {
    this.store.delete(key);
  }

  deleteByPrefix(prefix: string): void {
    for (const key of this.store.keys()) {
      if (key.startsWith(prefix)) this.store.delete(key);
    }
  }

  private cleanup(): void {
    const now = Date.now();
    for (const [key, entry] of this.store.entries()) {
      if (now > entry.expiresAt) this.store.delete(key);
    }
  }
}

// Quiz config cache: 5-minute TTL (quizzes change infrequently)
export const quizConfigCache = new SimpleCache<unknown>(5 * 60);

// Widget config cache: 10-minute TTL
export const widgetConfigCache = new SimpleCache<unknown>(10 * 60);

// Cache keys
export const cacheKeys = {
  quizConfig: (shop: string, slug: string) => `quiz:${shop}:${slug}`,
  widgetConfig: (shop: string) => `widget:${shop}`,
};

// Cache invalidation on quiz update (call from action handlers)
export function invalidateQuizCache(shop: string, slug: string): void {
  quizConfigCache.delete(cacheKeys.quizConfig(shop, slug));
}

export function invalidateShopCache(shop: string): void {
  widgetConfigCache.delete(cacheKeys.widgetConfig(shop));
  quizConfigCache.deleteByPrefix(`quiz:${shop}:`);
}
```

